(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["sm"] = {"ui":{"skip":"Alu i le anotusi","back":"← Toe foʻi i AI-gile","lang.button":"Gagana: {name}","lang.dialog":"Filifili se gagana","lang.search":"Suʻe gagana","lang.none":"E leai se gagana e tutusa","lang.notYet":"E leʻi faaliliuina le {name}","theme.aria":"Sui le autu: malamalama, pogisa pe uliuli","theme.toLight":"Sui i le autu malamalama","theme.toDark":"Sui i le autu pogisa","theme.toBlack":"Sui i le autu uliuli (uliuli moni, lelei mo lau OLED)","words.underline":"Tusi se laina i lalo o nei upu i le itulau","words.underlineHelp":"Tuu le kesa i luga pe tago i se upu e iai togi e vaai ai i lona uiga.","words.col.todo":"Kata ua filifilia mo nei: o le a amata e le 'au i nei mea.","words.col.doing":"O loʻo galulue se AI i le kata nei i le taimi nei.","words.col.review":"Ua uma e le AI e tasi le galuega; e siaki e se isi AI a o lei oʻo atu ia te oe.","words.col.verify":"O loʻo faatali ia te oe: faamaoni ma e fai mai pe e galue.","words.col.team":"O ou faamatalaga poʻo tali, o loʻo faatali mo le 'au e ave.","words.col.done":"Ua uma ma talia.","index.title":"AI-gile: lau ʻau AI faatupu polokalama, i le tasi laupapa","index.description":"O le AI-gile o se laupapa kanban mo ʻau tusi polokalama AI. E latou galulue a e moe oe; e te maua se faaputuga puupuu o mea e te filifili ai, suʻesuʻe ma talia.","hero.logoAlt":"Ata o le laupapa AI-gile","hero.h1.html":"Lau ʻau AI faatupu polokalama, i le tasi&nbsp;laupapa.","hero.alpha":"🐣 Pre-alpha tapunia","hero.alphaTitle":"Muamua ma le i uma: faafetai i lou taumafai!","hero.lede":"E latou fausia a e moe oe. E te ala mai i se faaputuga puupuu: ni nai fesili, ni nai mea e suʻe, ma le tasi pe lua taimane viole. Kiliki, talia, ma toe foʻi i lau kofe.","dl.windows":"Polokalama Windows","dl.browser":"Tatala i lau browser","dl.messenger":"📱 Messenger mo lau telefoni","dl.soon":"E le o toe umi","dl.notify":"🔔 Logo mai ina ua tatala","dl.notifySmall":"Alpha poʻo le beta","hero.secondary":"Agile, ae e le manaʻomia lava e le ʻau le kofe o le fono puupuu. (Ae latou te faia pea fono puupuu.)","pitch.h2":"AI-gile i le tele o upu e te manaʻo ai","pitch.lede":"Filifili se umi, mai le upu e tasi i le 144. O umi taʻitasi o se faamatalaga tuʻufaatasi, na tusia mo lena lapopoa. Toso le faʻasolo pe faaaoga ki aū o le keyboard.","pitch.rangeLabel":"Umi i upu","pitch.dice":"🎲 isi lomiga","pitch.words.one":"{n} upu","pitch.words.other":"{n} upu","pitch.letters.one":"{n} mataitusi","pitch.letters.other":"{n} mataitusi","pitch.chars.one":"{n} mataitusi","pitch.chars.other":"{n} mataitusi","count.line.html.one":"{n} kāte i luga o le laupapa nei","count.line.html.other":"{n} kāte i luga o le laupapa nei","people.humans.html.one":"👥 {n} tagata","people.humans.html.other":"👥 {n} tagata","people.agents.html.one":"🤖 {n} sui","people.agents.html.other":"🤖 {n} sui","people.working.html.one":"⚡ {n} o loʻo galulue nei","people.working.html.other":"⚡ {n} o loʻo galulue nei","pre.title":"AI-gile: o loʻo fausia se mea","pre.description":"O loʻo fausia se mea iinei: o se laupapa e fausia ai e ʻau AI mea e te manaʻo ai, ma aʻoaʻo atu ia te oe a o latou galulue. O se pre-alpha tapunia ma uo mo le taimi nei.","pre.h1":"O loʻo fausia se mea iinei. 🤫","pre.line":"O se laupapa e fausia ai e ʻau AI mea e te manaʻo ai, ma aʻoaʻo atu ia te oe a o latou galulue. O se pre-alpha tapunia ma uo mo le taimi nei.","pre.btn":"🔔 Logo mai ina ua tatala","pre.peek":"I tua o le tioata: le laupapa moni, ola. O kāte uma o se laina lanu.","pre.peekFake":"I tua o le tioata: le foliga o se laupapa o loʻo galue.","pre.night":"🌙 O le leoleo o le pō e pule · 😴 o loo malolo le tagata","features.aria":"O le a le mea e faia","f.pile.h":"Le tasi faaputuga mo oe","f.pile.html":"O <b>Mo oe</b> e tuufaatasia mea uma o loo faatali ia te oe, i poloketi uma: fesili, mea e suʻesuʻe, galuega e na o le tagata e mafai ona faia. O lau laina e taʻu atu le mea o le a sosoo ai ma le umi.","f.sleep.h":"ʻAu e galulue a e moe oe","f.sleep.p":"O poloketi taʻitasi e iai se taʻitaʻi ma se ʻau o sooupu AI. Tusi se faamatalaga i luga o se kāte ona ala lea o le ʻau, faia le galuega, ma toe tuuina atu ma laasaga e mafai e se tagata vaivai ona mulimuli ai.","f.tester.h":"E muamua siaki e se AI suʻesuʻe","f.tester.p":"Aʻo leʻi oo atu se mea ia te oe, e mulimuli le suʻesuʻe i laasaga i se kopi o le polokalama ma faaali le mea na ia vaai i ai, faatasi ma se ata o le lau. Iloilo mea na pasia ma talia i le tasi kiliki.","f.proof.h":"Faamaoniga, e le o folafolaga","f.proof.p":"O le tuuina atu taʻitasi e faaali ai le mea na suia: faila, eseesega, ata o le lau. E te le manaʻomia ona tatalaina polokalama uma e vaai pe ua uma.","f.chat.h":"Talanoa ma ou taʻitaʻi","f.chat.p":"O se laina e pei o Discord: le tasi ata mo poloketi taʻitasi, taimane viole mo mea e manaʻomia ai oe. Auina atu se manatu i se taʻitaʻi; e ia faia ma kāte ma se fuafuaga, faatasi ma se faamau ✅ Alu.","f.tidy.h":"E faʻatulaga e ia lava","f.tidy.p":"O kāte felavasaʻi e tuufaatasia, o ulutala fenumiai e faasaʻoina, ma o se siakiga token e tausia le code ia mamā. E le tele mea e sui ai, e le tele mea e mafaufau ai.","f.private.h":"O oe lava, i lau komepiuta","f.private.li1":"E galue le laupapa i lau lava masini ma e na o oe e tali atu ai.","f.private.li2":"O feʻau tuusao i le va o tagata ua faamaufaailogaina mai le pito i le pito.","f.private.li3":"E leai ni akauni, e leai ni mea e siaki ai oe, e leai ni cookies.","f.lang.h":"I lau gagana","f.lang.p":"E sili atu i le 120 gagana, mai le Holani, Uelisi ma Iapani i le pirate, Yoda ma Klingon, faatasi ma se sui vave i le Igilisi mo upu faʻapitoa.","f.service.h":"Mai se manatu i se auaunaga moni","f.service.p":"Na e fausia se mea i le AI ua faaaoga nei e tagata? Faailoga o se auaunaga ma o le a fesoasoani le laupapa ia e faatautaia lelei: siakiga uptime, se itulau o le tulaga lautele, faalavelave ma se tusiga, suiga e manaʻomia se Go, faʻasaoga e siakiina i aso uma. E aʻoaʻo atu e le Fesoasoani laasaga taʻitasi a o e alu.","msgr.h2":"AI-gile Messenger: lau ʻau i lau taga","msgr.p1":"Talanoa ma lau ʻau AI e aunoa ma le tatalaina o le laupapa. Talatalanoa ma ou taʻitaʻi poloketi ma au uo, ma vaai i laasaga suʻega o se kāte ma tali i ai, mai lau telefoni uma lava.","msgr.p2":"Ina ia fesoʻotaʻi, sikeni se QR code i lau laupapa. O le taimi muamua? O se talanoaga demo faauo o le a faʻaali atu ia te oe mea uma.","msgr.when":"Android muamua, ona sosoo ai lea ma se lomiga i luga o le upega tafaʻilagi mo telefoni ma iPhone.","msgr.who":"Lou taʻitaʻi poloketi","msgr.b1":"Ua sauni le toe faaleleia o le dark mode. E te manaʻo i laasaga suʻega?","msgr.b2":"Ioe faamolemole!","msgr.b3":"1. Tatala Settings. 2. Filifili Dark. E foliga saʻo?","tl.aria":"Taimi mai le talanoaga muamua i le fuafuaga","tl.h2":"Mai le talanoaga muamua i mea o le a sosoo ai","tl.lede":"Aso ma taimi moni, i lou itu taimi. Ina ua mavae le aso nei o le fuafuaga, e leai ni aso o folafolaina.","tl.today":"Aso nei","tl.planned":"fuafuaina","tl.doing":"o faia","tl.cards.one":"{n} kāte","tl.cards.other":"{n} kāte","join.h2":"Auai mai","join.lede":"O loo fausia AI-gile e se tagata ese e iai lana ʻava, e iai lona AuDHD ma ni nai taua ma le soifua mālōlōina o le mafaufau, ma le tele o sooupu onosaʻi. O le taimi nei e faalilolilo, i se alpha tapunia ma uo. E te manaʻo e taumafai pe a tatala?","join.btn":"Lesisita le fiafia","join.small":"O le a matou tusi atu i le imeli, e leai se isi mea","footer.tag":"AI-gile. E leai ni mea e siaki ai oe, e leai ni cookies, e leai se kofe o le fono puupuu.","footer.licence":"Laisene pisinisi","footer.status":"Tulaga","footer.privacy":"Mea matou te teuina","footer.thanks":"Valaʻau, faafetai ia ChilledChat","form.sending":"O auina atu…","form.failed":"E leʻi galue: toe taumafai mulimuli ane.","form.offline":"E leʻi mafai ona oo atu i AI-gile: toe taumafai mulimuli ane.","form.keep":"Matou te faaaogaina na o le tali atu ia te oe, ona tapeese ai lea. E leai ni mea e siaki ai oe, e leai ni cookies.","form.keepLink":"Mea matou te teuina","interest.title":"AI-gile: logo mai ina ua tatala le alpha","interest.description":"Tuu mai lau imeli e iloa ai pe a tatala le alpha poʻo le beta tapunia o AI-gile.","interest.h1":"🔔 Logo mai ina ua tatala","interest.lede":"O AI-gile o loo i le pre-alpha tapunia. Tuu mai lau imeli ona matou tusi atu lea i le tasi taimi, pe a iai se avanoa mo oe.","interest.email":"Lau imeli","interest.which":"O le fea suega?","interest.alpha":"Alpha tapunia: muamua, ma le faigata, e tele suiga","interest.beta":"Beta: sili atu le mausali, mulimuli ane","interest.both":"Se tasi, po o le fea e muamua mai","interest.submit":"Tuu aʻu i le lisi","interest.thanks":"Faafetai! O iai oe i le lisi.","licence.title":"AI-gile: laisene pisinisi","licence.description":"E te faaaogaina AI-gile i lau pisinisi? Talosaga mo se laisene pisinisi e leai se totogi.","licence.h1":"📜 Laisene pisinisi","licence.lede":"E te faaaogaina AI-gile i le galuega? Taʻu mai po o ai oe ma le mea e te faia. Afai e aogā, e leai se totogi o le laisene.","licence.company":"Kamupani","licence.website":"Uepisaite","licence.what":"O le a le mea e te faia","licence.how":"Le auala e fesoasoani ai i le lalolagi","licence.email":"Imeli","licence.submit":"Talosaga","licence.thanks":"Faafetai! O le a matou toe tali atu i le imeli.","status.title":"Tulaga o AI-gile","status.h1":"Tulaga o AI-gile","status.quiet":"Ua filemu uma","status.intro":"O galue AI-gile i le taimi nei? E siaki e lenei itulau le uepisaite, faasoa o laupapa, telefoni ma le download i minute uma e 5.","status.up":"O galue (tali mai i le {ms} ms)","status.slow":"E leʻi tali mai i le siaki mulimuli, o toe taumafai","status.down":"Ua pau: e leʻi tali mai i siaki mulimuli e lua","status.svc.web":"Uepisaite","status.svc.web.offers":"Lenei saite: o le a le AI-gile, ma le pepa o le fiafia","status.svc.boards":"Faasoa o laupapa","status.svc.boards.offers":"Laupapa lautele, feʻau i le va o uo ma valaaulia","status.svc.calls":"Telefoni","status.svc.calls.offers":"Leo, vitio ma le faasoa o le lau i totonu o AI-gile","status.svc.download":"Download","status.svc.download.offers":"Le polokalama faapipii mo Windows ma fesoʻotaʻiga valaaulia","status.checking":"O siaki…","status.offline":"E le mafai ona oo atu i le auaunaga o le tulaga i le taimi nei (o toe taumafai)","status.updated":"faafouina {ago}","status.justNow":"ua na o nei","status.min":"{n} minute ua mavae","status.hours":"{n} itula ua mavae","status.days":"{n} aso ua mavae","privacy.title":"AI-gile: mea matou te teuina","privacy.h1":"Mea matou te teuina","privacy.lede":"I se faapuupuuga: na o mea e te auina mai, ma e le umi.","privacy.only":"Na o mea e te auina mai: mea e te tusia i se pepa, e pei o lau imeli. E leai se isi mea e uiga ia te oe.","privacy.sealed":"Ua faamaufaailogaina ina ia le mafai e le matou server ona faitau: i lau browser aʻo leʻi alu (i se browser tuai, i le taimi lava e taunuu ai). Na o le matou lava laupapa e mafai ona tatalaina.","privacy.server":"E tapeese mai le server i le taimi lava e oo ai i le matou laupapa. Soo se mea o i ai pea pe a mavae aso e 30 e tapeese lava.","privacy.board":"Matou te teuina i le matou laupapa seʻia matou tali atu ia te oe, ona tapeese ai foi lea iina.","privacy.none":"E leai ni mea e siaki ai oe, e leai ni cookies, e leai ni suʻesuʻega o le faaaogaina.","privacy.local":"O lau gagana ma lau filifiliga o le malamalama po o le pogisa e tumau i lau lava browser. E le auina mai lava i matou.","privacy.ask":"E te manaʻo ia vave ona tapeese? Tali mai i la matou imeli ma taʻu mai.","live.h2":"Matamata i lona fausiaina, ola","live.caption":"Ua natia kāte uma: e te va'ai i foliga o le galuega, e le o ni upu.","live.watching.one":"ola: {n} o matamata","live.watching.other":"ola: {n} o matamata","live.last.now":"Na sii le kāte mulimuli i le taimi nei lava","live.last.min.one":"Na sii le kāte mulimuli i le {n} minute ua mavae","live.last.min.other":"Na sii le kāte mulimuli i minute e {n} ua mavae","live.last.hour.one":"Na sii le kāte mulimuli i le {n} itula ua mavae","live.last.hour.other":"Na sii le kāte mulimuli i itula e {n} ua mavae","live.last.day.one":"Na sii le kāte mulimuli i le {n} aso ua mavae","live.last.day.other":"Na sii le kāte mulimuli i aso e {n} ua mavae","live.offline":"O lo'o malolo sina le fa'amaumauga ola. Toe afio mai a e le'i umi.","live.cols":"Backlog|E fai|O loʻo faia|O loʻo siaki e le 'au|Mo oe e test|Mo le 'au|Ua uma"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Tuuina."]},{"n":2,"texts":["Kanban robots.","Sui, faatulagaina.","Manatu, fausia."]},{"n":3,"texts":["Kanban mo robots.","Manatu e avea gaoioiga.","Kanban sui, leai totogi."]},{"n":5,"texts":["Laupapa kanban e taitaia e sui.","Tusi kāte. E fausia e sui.","Leai totogi, i totonu, suʻesuʻeina, malie."]},{"n":8,"texts":["Laupapa kanban leai totogi e galue ai sui AI.","Tusi se manatu. E fausia e sui. E te talia.","Agile mo se tagata ma robots onosaʻi e tele."]},{"n":13,"texts":["Laupapa kanban i lau komepiuta, e piki kāte ai sui AI e galue.","Tusi se manatu. E fausia e sui. Suʻesuʻe e siaki. Oe e talia.","Leai totogi, leai teugatupe, leai nofoaga mulimuli: se laupapa, ni robots, ma oe e pule."]},{"n":21,"texts":["O le AI-gile o se laupapa kanban mo galulue ma sui AI e tusi polokalama. E latou piki kāte; e te suʻesuʻe ma talia.","Poloketi taʻitasi e iai se taʻitaʻi ma ʻau sui AI. Tusi se faamatalaga i se kāte, ona amata lea o le galuega.","Laupapa galuega totino e leai se totogi, i lau lava komepiuta. E robots le ʻau. O oe e fai atu ioe."]},{"n":34,"texts":["Tuu manatu i luga o le laupapa. E liliu e se ʻau sui AI i gaoioiga e galue, suʻesuʻe, ma toe tuuina atu ma laasaga. E leai se mea ua uma seʻia e fai mai oe.","O le AI-gile o se laupapa kanban na fausia e Rich faatasi ma sui AI o loo ia pulea nei. E leai se totogi, e galue i lau komepiuta, ma faasoa i uo, e le faatauina.","Mafaufau i se laupapa kanban masani, ma koluma mai le Backlog i le Ua uma, ae o kāte e piki e sui AI. Latou lipotia le alualu i luma, fesili pe a tu, ma faatali pea i lau faatagaga."]},{"n":55,"texts":["O le AI-gile o se laupapa kanban e fausia le ʻau i sui AI. O poloketi taʻitasi e iai se taʻitaʻi e fuafuaina le galuega ma fesoasoani e faia. A uma se gaoioiga, e suʻesuʻe e se AI suʻesuʻe ma ave ai se ata o le mataʻitusi, ona alu lea i lau faaputuga. Talia, pe tusi se faamatalaga ona toe faia lea e latou.","Na amata o se auala e mulimuli ai le tagata e tasi i le tele o fonotaga tusi polokalama AI, ona tupu lea i se laupapa moni. E galue i lau masini, e leai se teugatupe, e leai ni nofoaga mulimuli. E leai se totogi mo uo. E le i uma, ia faatalitali i ni pito faigata.","O le faamatalaga faamaoni lea. E tatau pea ona e maua manatu, ma e tatau pea ona e siaki taunuuga. O le AI-gile e faia mea uma i le va: e tausia kāte i le faasologa, ala le sui saʻo pe a e tusi se faamatalaga, faaali saʻo le mea na suia, ma tuu mea uma i se faaputuga puupuu mo oe."]},{"n":89,"texts":["O le AI-gile o se laupapa kanban e leai se totogi i lau komepiuta. I poloketi taʻitasi e iai se ʻau sui AI: se taʻitaʻi e liliu au manatu i kāte ma se fuafuaga, ma fesoasoani e piki kāte. A fausia se mea, e mulimuli se AI suʻesuʻe i laasaga ma faaali le mea na ia vaai i ai. Ona faatali lea i se faaputuga e igoa Mo oe. E te talia, pe tusi se faamatalaga ona toe taumafai lea. E leai se mea e oo i le Ua uma e aunoa ma oe.","Nisi mea e te le faatalitalia. O se leoleo po e faatumu le koluma E fai a e moe oe, ma filifili kāte e le manaʻomia ai se tali. O se tagaga token e faaali le aofaʻi e faaaoga e sui, ma o le Auala e leai ni token e taofi ai. E mafai ona e feʻau atu i uo, faamaufaailogaina mai le pito i le pito. E tautala le laupapa i le tusa ma le 120 gagana, e aofia ai Holani, pirate ma Klingon. E leai se totogi, ma e leai se tasi o taumafai e faatau atu.","O le AI-gile o se poloketi laʻitiiti totino, e le o se kamupani. Na manaʻo Rich e tausia ni poloketi tusi polokalama AI e aunoa ma le tatalaina o polokalama uma, o lea na ia fausia ai se laupapa faatasi ma sui, ona faaaoga lea e fausia le vaega o totoe. O loo i le pre-alpha tapunia: e galue, e tele lava, mo ni uo e toʻaitiiti. E leai se itulau o tau, e leai se nusipepa. Afai e aogā, talosaga e taumafai pe a sili atu le tatala."]},{"n":144,"texts":["O le AI-gile o se laupapa kanban mo le tagata e tasi ma le tele o sui AI. E galue i lau lava komepiuta ma e leai lava se totogi. E te faaopoopo poloketi, ma taʻitasi e maua se taʻitaʻi ma se ʻau laʻitiiti. E te talanoa ma le taʻitaʻi, e pei o Discord, ma faamatala se manatu; e liliu e le taʻitaʻi i kāte ma se fuafuaga, ona faatali lea seʻia e kiliki Alu. E faia e le ʻau kāte e tusa ai ma le faamuamua, e faaaoga se laina poloaiga faigofie na faia mo faiga gagana. Aʻo leʻi toe foʻi se mea ia te oe, e mulimuli se AI suʻesuʻe i laasaga i se kopi o le polokalama ma faapipiʻi se ata o le mataʻitusi. O galuega ua uma e oo i lau faaputuga faatasi ma faila ua suia ma eseesega. E te talia, pe tuu se faamatalaga ona ala lea o le ʻau ma toe taumafai. Na o oe e mafai ona e suia se kāte i le Ua uma.","O se aso ma AI-gile, tusa lava. I le afiafi e te tuu ni faamatalaga: o lenei faamau o loo i se mea sese, o lena lisi e tatau ona faatulagaina, e mafai ona tatou maua se auala pogisa. E te alu e moe. E faitau e sui faamatalaga, faia suiga, suʻesuʻe ma toe tuuina atu ia te oe. Afai e mutu le koluma E fai, e faatumuina e le leoleo po mai le backlog i kāte e le manaʻomia ai se tali mai ia te oe. I le taeao o loo iai se faaputuga puupuu: ni fesili e ono ma ni mea e suʻesuʻe, taʻitasi ma laasaga e mafai e se tagata moeiini ona mulimuli ai ma se ata o loo galue. E te alu i totonu, talia mea lelei ma toe auina atu isi. Ona e taumafa lea o le taeao, lea e le mafai pea e sui ona fesoasoani i ai.","Muamua, le mea e le o le AI-gile. E le o se startup, e le o faatauina, ma e leai se tasi o aoina au faamatalaga. O se laupapa e leai se totogi e galue i lau komepiuta, e leai ni teugatupe, e leai ni nofoaga mulimuli ma e leai ni cookies. O le mea e iai: o se nofoaga e tasi mama e vaai ai i poloketi tusi polokalama AI uma i le taimi e tasi, ma se ʻau o sui e faia kāte ma oe e faia filifiliga. E tuufaatasia kāte felavasaʻi, faasaʻo ulutala fenumiai, ma mataʻituina ia tumau le code vaivai. E tautala i le tusa ma le 120 gagana, mai le Holani ma le Flemish i le pirate ma le Klingon. O loo i le pre-alpha tapunia, o lea e faigata i nisi pito. Afai e foliga manaia, talosaga ma le agalelei ona e maua lea ma le vave."]}],"quips":{"1":"Le upu e tasi. Natia. Masalo e sili.","3":"Upu e tolu. E sili atu le faamaoni nai lo le tele o itulau o oloa.","8":"Upu e valu. E puupuu pea nai lo se fono puupuu.","21":"O umi o story points, i le ala. Ioe, e faapea lava.","55":"Upu e lima sefulu ma le lima. E lua kāte na uma aʻo e faitau.","144":"O le mea umi lea. E leai se 233. Ua alu e moe sui."}},"timeline":{"first-idea.name":"Le manatu muamua","first-idea.line":"O le talanoaga sili ona muamua, aʻo leʻi iai se code.","first-board.name":"Le laupapa muamua","first-board.line":"O se laupapa e mulimuli i lona lava fausiaga: kāte, koluma, toso ma tuu, poloketi.","team-roles.name":"ʻAu ma tofiga","team-roles.line":"Faamatalaga o sui, faʻataʻitaʻiga o ʻau, avanoa ma o ai e faia le a.","install.name":"Faapipiʻiga ma lomiga","install.line":"O se zip e mafai e se uo ona faapipii, faafouga otometi, auala ma toe foʻi.","usage-saver.name":"Faasaoina o le faaaogaina","usage-saver.line":"Fuaina le tau o le faatinoga, tausia le code e vaivai, faasaoina lau tapulaa.","friends.name":"Uo ma le faasoaina","friends.line":"Feʻau tuusao, se relay faalilolilo, valaaulia, tofiga ma poloketi faasoa.","languages.name":"Gagana","languages.line":"O tusitusiga uma o le mataʻitusi i se faila gagana, ma le Holani ma le Flemish muamua.","ai-tester.name":"AI suʻesuʻe","ai-tester.line":"E muamua siaki e se suʻesuʻe tuuina atu uma ma faaali le mea na ia vaai i ai.","website.name":"Le initaneti","website.line":"aigile.lol, le teaser ma lenei taimi.","streaming.name":"Talanoaga ma faasalalauga","streaming.line":"Discord, Twitch, OBS, auala faasalalau, GIF ma emoji.","no-ai.name":"Lomiga e leai se AI","no-ai.line":"O se laupapa mo tagata e tusi polokalama e aunoa ma AI, ma laupapa lautele.","night-watch.name":"Leoleo po","night-watch.line":"O se leoleo ma se Scrum Master e tausia ʻau i galuega a e moe oe.","p-more.name":"Isi mea uma","p-more.line":"Manatu laiti o loo faatali pea i le latou taimi.","p-android.name":"Telefoni ma Android","p-android.line":"Oo atu i lau laupapa mai se telefoni, ona sosoo ai lea ma se polokalama Android.","p-release.name":"Alpha ma mulimuli ane","p-release.line":"Alpha tapunia, le initaneti ola, ona sosoo ai lea ma le beta.","p-languages.name":"Sili atu gagana","p-languages.line":"E 130 gagana, ma se auala faʻalauteleina o le gagana mo i latou o aʻoaʻo.","p-engines.name":"Sili atu afi AI","p-engines.line":"Filifili Claude, Codex, Gemini, Copilot po o Cursor mo sooupu taʻitasi.","p-pro.name":"Faiga faapolofesa","p-pro.line":"Faailoga o lamatiaga, faitotoʻa tuufaatasia, kāte o mea e tutupu ma puipuiga.","p-self.name":"Tausia oe","p-self.line":"Auala o le vaivai, faamanatu o le tausiga o oe lava ma le 4:20.","p-servers.name":"Server ma le tuputupu aʻe","p-servers.line":"Setiina lautele o server, tofiga ma fuafuaga mo le tuputupu aʻe.","p-livestream.name":"Faaopoopoga faasalalau","p-livestream.line":"Talanoaga Twitch, emoji faapitoa ma se vaaiga ola lautele."},"words":{"button":"📖 Upu faʻapitoa","h":"📖 Upu ua faamatalaina","intro":"Aʻoaʻoga e leai se totogi i le gagana faigofie: o upu uma e te feiloaʻi ai mai se manatu muamua seʻia oo i se auaunaga e faalagolago i ai tagata, faatasi ai ma le Agile, fausiaina, tausia saogalemu ma le galulue ma le AI i le ala.","search":"Su'e se upu…","none":"E leai se upu e fetaui.","close":"Tapuni","count":{"one":"{count} upu","other":"{count} upu"},"groups":[{"id":"idea","name":"💡 Manatu ma suʻesuʻega"},{"id":"plan","name":"🗺️ Fuafuaina o galuega"},{"id":"agile","name":"🔁 Auala agile e galue ai"},{"id":"build","name":"🛠️ Fausiaina"},{"id":"test","name":"🧪 Suʻega ma le tulaga lelei"},{"id":"change","name":"🔀 Suia ma le saogalemu"},{"id":"run","name":"🛎️ Faagaoioia o se auaunaga"},{"id":"sec","name":"🔒 Saogalemu ma le lilo"},{"id":"ai","name":"🤖 Galulue ma le AI"},{"id":"money","name":"💰 Tupe ma laisene"}],"list":[{"id":"discovery","g":"idea","word":"Suʻesuʻega (Discovery)","text":"O le vaega muamua e suʻe ai po o le a le faafitauli e tatau ona foia ma mo ai, a o leʻi fausia se mea.","also":["vaitaimi o suʻesuʻega","discovery","discovery phase"]},{"id":"problemstmt","g":"idea","word":"Faamatalaga o le faafitauli","text":"O se fuaitau e tasi pe lua e taʻu mai ai po o ai e iai le faafitauli, o le a lea, ma aiseā e taua ai, ina ia faasino tagata uma i le mea e tasi.","also":["problem statement","problem statements"]},{"id":"user","g":"idea","word":"Tagata faʻaoga (User)","text":"O se tagata e faʻaoga le mea e te fausia. O mea e manaʻomia e ia e mafua ai le galuega.","also":["tagata faʻaoga","user","users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Pāaga (Stakeholder)","text":"O so'o se tagata e manatu mamafa i le iʻuga o le galuega pe aʻafia ai, e pei o ē totogi, ē faʻaoga, po o ē lagolagoina.","also":["pāaga","stakeholder","stakeholders"]},{"id":"persona","g":"idea","word":"Persona (tagata faʻataʻitaʻi)","text":"O se tagata fatu ae e pei o se tagata moni, e fai ma sui o se ituaiga tagata faʻaoga, ina ia mafai e le 'au ona fesili: “E faigofie ea ia Sam lenei mea?”","also":["persona","personas"]},{"id":"userresearch","g":"idea","word":"Suʻesuʻega i tagata faʻaoga","text":"O le talanoa atu ma le matamata i tagata moni e iloa ai le mea latou te manaʻomia, nai lo le taumate.","also":["user research","user interviews","faatalatalanoaga ma tagata faʻaoga"]},{"id":"journey","g":"idea","word":"Malaga a le tagata faʻaoga","text":"O laasaga e faia e se tagata e maeʻa ai se mea, mai le taimi muamua na ia faalogo ai seʻia maeʻa, e aofia ai ma mea i fafo o lau oloa. O le tusiina e faaali ai le mea e mau ai i latou.","also":["user journey","user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Mea e tiga ai (Pain point)","text":"O se mea e faalavelave pe faatuai ai tagata i aso nei. E aveesea e oloa lelei ia mea.","also":["pain point","pain points"]},{"id":"assumption","g":"idea","word":"Manatu faapea (Assumption)","text":"O se mea e te talitonu i ai ae e leʻi siaki. O le tusiina o manatu faapea e faaali ai mea e tatau ona muamua suʻeina.","also":["assumption","assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Manatu e siaki (Hypothesis)","text":"O se taumatematega sili ona lelei e te fuafua e siaki, faatasi ai ma le mea e te faamoemoe e tupu, e pei o “e lesitala tagata pe a leai se totogi o le masina muamua”.","also":["hypothesis","hypotheses"]},{"id":"experiment","g":"idea","word":"Faataitaiga (Experiment)","text":"O se suʻega laʻitiiti ua fuafuaina e iloa ai pe aoga se manatu, a o leʻi tuuina atu i ai se tele.","also":["experiment","experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Faamaoniga o le manatu (PoC)","text":"O se taumafaiga vave e vaai pe mafai ona galue le manatu. E masani ona lafoina pe a maua le tali.","also":["PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Faataitaiga muamua (Prototype)","text":"O se faataitaiga muamua o le oloa, e masani o ata e mafai ona kiliki, e faataitai ai le manatu i tagata a o leʻi fausia atoatoa.","also":["prototype","prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe (ata faigofie)","text":"O se ata faigofie o se lau e faaali ai mea e tuu i ai, e leai ni lanu po o ni mea moni.","also":["wireframe","wireframes"]},{"id":"mockup","g":"idea","word":"Mockup (ata atoatoa)","text":"O se ata auiliili e faaali ai le foliga o se lau, ma lanu moni ma tusitusiga, ae leai se mea e galue.","also":["mockup","mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Mafuaaga o le pisinisi","text":"O mafuaaga e faia ai se poloketi: o le tau, o mea e maua mai ai pe faasaoina, ma lamatiaga.","also":["business case","business cases"]},{"id":"feasibility","g":"idea","word":"Mafai ona faia (Feasibility)","text":"Pe mafai moni ona fausia ma tausia se mea i le taimi, tupe ma tomai o iai.","also":["feasibility"]},{"id":"outcome","g":"idea","word":"Iʻuga (Outcome)","text":"O le suiga e te manaʻo i ai mo tagata, e pei o le toʻaitiiti o taimi tofia e misia. E sili ona taua nai lo le aofaʻi o mea e fausia.","also":["iʻuga","outcome","outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Mea na faia (Output)","text":"O se mea e faia e le 'au, e pei o se lau fou po o se lipoti. O le faia o se mea e le faapea ua fesoasoani ai i se tasi.","also":["output","outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Fua o le manuia (Success metric)","text":"O se numera e taʻu mai ai pe na ausia e le galuega lona faamoemoe, e pei o le toʻatele atu o tagata e faamaeʻa a latou oka.","also":["success metric","success metrics"]},{"id":"kpi","g":"idea","word":"Fua autu o le tulaga (KPI)","text":"O se numera taua e te mataʻituina e vaai pe lelei mea uma, e pei o le aofaʻi o tagata fou e lesitala i vaiaso taʻitasi.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Sini ma iʻuga autu (OKRs)","text":"O se auala e seti ai sini: o le sini e taʻu mai ai le mea e te manaʻo i ai, ma nai iʻuga autu o numera ia e faailoa ai ua e taunuʻu.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Oloa (Product)","text":"O le mea o loo fausia ma tausia mo ona tagata faʻaoga, e pei o se app, o se uepisaite po o se meafaigaluega.","also":["oloa","product","products"],"noTip":1},{"id":"vision","g":"plan","word":"Vaaiga o le oloa","text":"O se faamatalaga puʻupuʻu e taʻu mai ai po o ai e fesoasoani i ai le oloa ma le mea o loo agaʻi i ai i le taimi umi.","also":["product vision","vision statement"]},{"id":"po","g":"plan","word":"Pule o le oloa (Product owner, PO)","text":"O le tagata e filifili le mea e fausia ma le faasologa, ina ia galue pea le 'au i mea sili ona taua. I le AI-gile o oe lea.","also":["PO","product owner","product owners"]},{"id":"pm","g":"plan","word":"Faatonu o le oloa (Product manager, PM)","text":"O le tagata e vaaia le ala o le oloa: o faafitauli e foia, mo ai ma aiseā. E mafai foi ona uiga le PM i le faatonu o le poloketi (project manager), o lea siaki po o le fea.","also":["PM","faatonu o le oloa","product manager","product managers"]},{"id":"projmgr","g":"plan","word":"Faatonu o le poloketi (Project manager)","text":"O le tagata e faʻamautinoa e maeʻa le poloketi i le taimi ma le tupe ua fuafuaina, ma mataʻituina po o ai e faia le a mea ma i le a le taimi.","also":["faatonu o le poloketi","project manager","project managers"]},{"id":"roadmap","g":"plan","word":"Faafanua (Roadmap)","text":"O se fuafuaga lautele o mea o sau i masina o lumanaʻi, i se faasologa. E faaali ai le itu e alu i ai, e le o aso tonu, ma e suia a o e aʻoaʻoina.","also":["roadmap","roadmaps"]},{"id":"milestone","g":"plan","word":"Faailoga (Milestone)","text":"O se tulaga i le poloketi e tatau ona faailoa, e pei o le “ua ola le lomiga muamua” po o le “100 tagata faʻaoga”.","also":["milestone","milestones"]},{"id":"mvp","g":"plan","word":"Oloa laʻitiiti e aoga (MVP)","text":"O le lomiga sili ona laʻitiiti o se oloa e aoga pea mo tagata moni, ina ia mafai ona e aʻoaʻoina mai iā i latou i le amataga.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Mea e manaʻomia (Requirement)","text":"O se mea e tatau ona faia e le oloa pe a maeʻa, po o se tulaga e tatau ona iai.","also":["requirement","requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Tuaoi o galuega (Scope)","text":"O mea o loo aofia i le galuega, ma, e tutusa le taua, o mea e le aofia.","also":["scope","in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Faateleina o galuega (Scope creep)","text":"A faaopoopo pea ma pea mea i le galuega, sina vaega i lea taimi ma lea taimi, e aunoa ma se maliega i le taimi po o le tupe faaopoopo, ma e le iu lava ina maeʻa.","also":["scope creep","feature creep"]},{"id":"feature","g":"plan","word":"Gaoioiga (Feature)","text":"O se mea e mafai e le oloa ona faia mo tagata, e pei o le “toe seti lau upu faataga”.","also":["feature","features"],"noTip":1},{"id":"epic","g":"plan","word":"Galuega tele (Epic)","text":"O se vaega tele o galuega, e le mafai ona faia i le taimi e tasi, o lea e vaevaeina i kāte laiti.","also":["epic","epics"]},{"id":"story","g":"plan","word":"Tala a le tagata faʻaoga (User story)","text":"O se galuega laʻitiiti e tusia mai le itu o le tagata faʻaoga: “I a'u o se tagata faatau, ou te manaʻo e teu laʻu ato, ina ia mafai ona ou faamaeʻa mulimuli ane.” E amata ai se talanoaga i le mea e fausia.","also":["user story","user stories"]},{"id":"ac","g":"plan","word":"Tulaga e taliaina ai (AC)","text":"O siaki e tatau ona pasia e se kāte e ta'ua ua maeʻa, ua maliega a o leʻi amata le galuega, e pei o le “o loʻo iai pea le ato pe a ou alu ese ma toe ulufale mai”.","also":["AC","acceptance criteria"]},{"id":"task","g":"plan","word":"Galuega (Task)","text":"O se galuega e tasi e fai, e masani o se laasaga laʻitiiti o se tala (user story) e sili atu ona tele.","also":["task","tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Tikete (Ticket)","text":"O se isi upu mo le kāte: o se vaega o galuega po o se talosaga, e mataʻituina mai le amataga seʻia maeʻa.","also":["ticket","tickets"]},{"id":"priority","g":"plan","word":"Faamuamua (Priority)","text":"O le tele o le taua po o le faanatinati o se mea pe a faatusatusa ma isi mea uma, ina ia muamua galuega sili ona taua.","also":["priority","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Faamuamua galuega (Prioritisation)","text":"O le tuuina o galuega i le faasologa o le taua. O se auala masani o le MoSCoW: Must have (e tatau ona iai), Should have (e lelei pe a iai), Could have (e mafai ona iai), Won’t have this time (e le o lenei taimi).","also":["MoSCoW"]},{"id":"estimate","g":"plan","word":"Taumatematega (Estimate)","text":"O se taumatematega sili ona lelei i le tele po o le umi o se vaega o galuega. O se taumatematega, e le o se folafolaga.","also":["taumatematega","estimate","estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Togi o tala (Story points)","text":"O se auala e taumate ai le lapopoa o galuega i le faatusatusaina o kāte le tasi i le isi (“e tusa ma le faalua le lapopoa o lena”) nai lo itula. E le mo le faatusatusaina o 'au.","also":["story point","story points"]},{"id":"tshirt","g":"plan","word":"Fua o mitiafu (T-shirt sizing)","text":"O le taumate i le lapopoa o galuega e pei o le S, M, L po o le XL. E vave ma lava mo fuafuaga muamua.","also":["t-shirt sizes","T-shirt sizing"]},{"id":"poker","g":"plan","word":"Pokā o fuafuaga (Planning poker)","text":"O se taaloga e taumate ai: e faaali e tagata uma se kāte o le lapopoa i le taimi e tasi, ona faamatala lea e i latou na faaali le fua aupito tele ma le aupito laʻitiiti pe aiseā.","also":["Scrum poker","planning poker"]},{"id":"dependency","g":"plan","word":"Faalagolago (Dependency)","text":"A le mafai ona amata pe maeʻa se vaega o galuega seʻia maeʻa le isi.","also":["dependency","dependencies"]},{"id":"blocker","g":"plan","word":"Taofiofi (Blocker)","text":"So'o se mea o taofia ai le agaʻi i luma o le galuega i le taimi nei, e pei o se tali e leʻi maua po o se meafaigaluega ua malepe.","also":["blocker","blockers"]},{"id":"deadline","g":"plan","word":"Aso mulimuli (Deadline)","text":"O le aso e tatau ona maeʻa ai se mea.","also":["deadline","deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Mea e momoli atu (Deliverable)","text":"O se mea moni e faia e le galuega ma tuuina atu, e pei o se lau e galue pe o se lipoti.","also":["deliverable","deliverables"]},{"id":"forecast","g":"plan","word":"Valoaga (Forecast)","text":"O se valoaga o le mea e foliga mai e tupu, e pei o le taimi e maeʻa ai le galuega, e faavae i mea ua e iloa i le taimi nei.","also":["forecast","forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Fua (Metric)","text":"So'o se mea e te fuaina ma mataʻituina i le aluga o le taimi, e pei o asiasiga i itulau po o le umi e faia ai se faaleleiga.","also":["metric","metrics"]},{"id":"feedback","g":"plan","word":"Manatu faafoʻi (Feedback)","text":"O mea e taʻu atu e tagata e uiga i lau galuega, lelei ma le leaga. O le maua vave ma soo o le tulaga autu lea o le Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"O le lisi faatali o manatu ma galuega e leʻi fuafuaina, ma mea sili ona taua i luga. E leai se mea iina e galueina seʻia siitia i le E fai."},{"id":"sprint","g":"agile","word":"Sprint","text":"O se vaitaimi puʻupuʻu ua tapulaʻa o galuega (e masani o le vaiaso e tasi pe lua, e le sili atu i le masina) ma se sini ma se seti kāte ua malilie e faamaeʻa.","also":["sprints"]},{"id":"standup","g":"agile","word":"Fonotaga puʻupuʻu","text":"O se siakiga vave i aso uma: o le a le mea na faia e sui taʻitasi o le 'au, o le a le mea latou te faia a sosoo, ma le mea o taofia ai i latou. I le Scrum e ta'ua o le daily scrum.","also":["fonotaga puʻupuʻu","standup","stand-ups","daily scrum","daily stand-up"]},{"id":"kanban","g":"agile","word":"Kanban","text":"O se auala e galue ai e feoaʻi ai kāte i luga o koluma o se laupapa (e pei o E fai, O loʻo faia, Ua uma) ma e faatapulaʻa e le 'au le tele o mea e faia i le taimi e tasi, ina ia faaauau le tafe o galuega."},{"id":"wip","g":"agile","word":"Tapulaʻa WIP","text":"O le WIP o le puʻupuʻu mo work in progress. O le tapulaʻa WIP o le aofaʻi sili o kāte e tatau ona taofi e se koluma i le taimi e tasi, ina ia faamaeʻa e le 'au mea a o leʻi amata isi.","also":["WIP","WIP limit"]},{"id":"dod","g":"agile","word":"Faauigaga o le Uma","text":"O le lisi siaki puupuu a le ʻau o le uiga o le “uma”, e pei o le ua suʻeina ma faamatalaina, a o leʻi tuuina atu se kāte iā te oe. O lona masaga, o le Faauigaga o le Sauni, e faailoa mai pe a manino lelei se kāte e amata ai.","also":["Definition of Ready","DoD","DoR","Faauigaga o le Sauni"]},{"id":"retro","g":"agile","word":"Toe iloilo","text":"O se toe iloilo masani i le auala e galue ai le 'au, e malilie ai i le tasi pe lua mea e faaleleia i le isi taimi. Puʻupuʻu mo retrospective. I le AI-gile e fautua mai e le retro se suiga i auala e galue ai le 'au, ma e te fai atu Alu po o E leʻi.","also":["retro","retrospective"]},{"id":"swarm","g":"agile","word":"Fuifui","text":"Lima uma i le galuega: e tele tagata e tuu ese isi galuega e faaleleia faatasi se mea e tasi e faanatinati seʻia foia. I le AI-gile e fesoasoani 'au uma i le poloketi e tasi, ma e faatali isi poloketi i le taimi lea.","also":["swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"I le Scrum, o le tagata e fesoasoani i le 'au e galue lelei: aveese mea e taofia ai i latou, tausia fonotaga i le ala saʻo ma aʻoaʻo masani lelei, e aunoa ma le pule i se tasi. I le AI-gile e vaai le Lead Scrum Master i kāte ua mau, unaʻi 'au ma faamanatu atu iā te oe mea o loo faatali, i poloketi uma.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"O se auala e galue ai i laasaga laiti: fausia sina mea, faaali soo iuga moni, aʻoaʻoina mai le mea e fai mai ai tagata ma suia le fuafuaga a o alu, nai lo le fuafuaina o mea uma i le amataga.","also":["Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Agile Manifesto (Folafolaga Agile)","text":"O se faamatalaga puʻupuʻu na tusia i le 2001 e tagata fai polokalama. Na tuu muamua ai tagata, iuga e galue, galulue vavalalata ma tagata faatau ma le tali i suiga, nai lo fuafuaga mamafa ma pepa tele.","also":["Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"O le auala tuai e galue ai: fuafua mea uma, ona fausia atoa lea, ona suʻe atoa lea, tasi le laasaga i le isi. E faigata ma taugata suiga i le taimi mulimuli.","also":["waterfall model"]},{"id":"iteration","g":"agile","word":"Taamilosaga (Iteration)","text":"O le taamilosaga e tasi o le fausiaina o se mea, siaki ma faaleleia. O galuega Agile o se filifili o ia taamilosaga, ma o le sprint o se ituaiga e tasi.","also":["iteration","iterations"]},{"id":"increment","g":"agile","word":"Faaopoopoga (Increment)","text":"O se vaega fou e galue ua faaopoopo i le oloa i se sprint po o se taamilosaga o galuega, e faatasi ma mea sa iai.","also":["increment","increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"O se auala Agile e lauiloa e galue ai: e galue se 'au laʻitiiti i sprint puʻupuʻu agaʻi i se sini, ma tofiga ua mautu ma ni nai fonotaga masani e fuafua, siaki ma faaleleia ai."},{"id":"scrumteam","g":"agile","word":"'Au Scrum (Scrum team)","text":"O le vaega laʻitiiti e galue i le Scrum: o se pule o le oloa, o se Scrum Master ma tagata atiaʻe.","also":["Scrum team","Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Fonotaga Scrum (Scrum events)","text":"O fonotaga masani i le Scrum: o le fuafuaga o le sprint, le scrum i aso uma, le iloiloga o le sprint ma le retro. E toʻatele tagata e taʻua i latou o ceremonies.","also":["ceremonies","Scrum ceremonies","Scrum events"]},{"id":"sprintplan","g":"agile","word":"Fuafuaga o le sprint (Sprint planning)","text":"O le fonotaga i le amataga o se sprint e malilie ai le 'au i le mafuaaga e taua ai le sprint, o ā kāte e ave ma le auala e amata ai.","also":["sprint planning","planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Sini o le sprint (Sprint goal)","text":"O se fuaitau e tasi e taʻu mai ai le mea e fai ai le sprint. E mafai ona suia galuega laiti i le ala, pe a ausia pea le sini.","also":["sprint goal","sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Lisi o le sprint (Sprint backlog)","text":"O kāte ua filifilia mo le sprint o iai nei, faatasi ai ma le fuafuaga a le 'au e faia ai.","also":["sprint backlog","sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Lisi o galuega o le oloa (Product backlog)","text":"O le lisi atoa i le faasologa o mea uma e ono fausia mo le oloa, o mea sili ona taua i luga. E suia pea a o e aʻoaʻoina.","also":["product backlog","product backlogs"]},{"id":"productgoal","g":"agile","word":"Sini o le oloa (Product goal)","text":"O le iʻuga tele atu o loo agaʻi i ai le oloa, e fesoasoani i le 'au e filifili le mea e fai a sosoo.","also":["product goal","product goals"]},{"id":"refinement","g":"agile","word":"Faaleleia o le backlog (Backlog refinement)","text":"O le toe iloiloina soo o le backlog e faamaopoopo, vaevae, faasolosolo ma faaopoopo auiliili i kāte, ina ia sauni e ave. E ta'ua foi o backlog grooming.","also":["backlog refinement","backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Iloiloga o le sprint (Sprint review)","text":"O se fonotaga i le iʻuga o se sprint e faaali ai e le 'au mea ua maeʻa ma faalogo i manatu o tagata, e filifili ai le mea e sosoo ai.","also":["sprint review","sprint reviews"]},{"id":"demo","g":"agile","word":"Faaaliga (Demo)","text":"O le faaali o galuega ua maeʻa o loo galue, i le taimi lava lea, i tagata na ole mai.","also":["demo","demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Tapulaʻa taimi (Timebox)","text":"O se aofaʻi taimi ua tofia mo se mea. A uma, e te taofi, e tusa lava pe leʻi maeʻa mea uma.","also":["timebox","timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Saosaoa (Velocity)","text":"O le aofaʻi o galuega e masani ona maeʻa e se 'au i se sprint, e faaaoga e fuafua ai le aofaʻi e ave i le isi taimi. E le o se togi mo le malosi o galuega a tagata.","also":["velocity","team velocity"]},{"id":"capacity","g":"agile","word":"Malosi e galue (Capacity)","text":"O le aofaʻi o galuega e mafai e le 'au ona ave i se vaitaimi, a uma aso malolo ma isi galuega.","noTip":1},{"id":"burndown","g":"agile","word":"Siata faaitiitia (Burndown chart)","text":"O se siata o galuega o totoe i se sprint e faaitiitia i aso taʻitasi. A tumau laugatasi le laina, e iai se mea ua mau.","also":["burndown","burn-down chart","burndown chart"]},{"id":"burnup","g":"agile","word":"Siata faateleina (Burnup chart)","text":"O se siata o galuega ua maeʻa e faateleina i le aluga o le taimi, i tafatafa o le aofaʻi atoa na fuafuaina, ina ia e iloa ai po o afea e te taunuʻu ai.","also":["burnup","burn-up chart","burnup chart"]},{"id":"kanbanboard","g":"agile","word":"Laupapa Kanban (Kanban board)","text":"O le laupapa lava ia: o se koluma mo laasaga taʻitasi o le galuega, ma kāte e feoaʻi.","also":["Kanban board","Kanban boards"]},{"id":"pullsys","g":"agile","word":"Faiga toso (Pull system)","text":"O se auala e galue ai e amata ai galuega fou pe a iai se avanoa o se tasi e ave, nai lo le tuuina atu i se tagata ua tumu lana galuega.","also":["pull system","pull-based"]},{"id":"flow","g":"agile","word":"Tafega (Flow)","text":"O le lelei o le feoaʻi o galuega i luga o le laupapa. O le tafega lelei e uiga o kāte e feoaʻi pea, e le faaputu.","also":["flow","flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Taimi atoa (Lead time)","text":"O le umi e alu mai le taimi na ole ai se tasi mo se mea seʻia maeʻa.","also":["lead time","lead times"]},{"id":"cycletime","g":"agile","word":"Taimi o le galuega (Cycle time)","text":"O le umi e alu ai se kāte mai le taimi e amata moni ai le galuega seʻia maeʻa.","also":["cycle time","cycle times"]},{"id":"throughput","g":"agile","word":"Aofaʻi ua maeʻa (Throughput)","text":"O le aofaʻi o kāte e maeʻa i le vaiaso, po o so'o se taimi tofia.","also":["throughput","throughput rate"]},{"id":"bottleneck","g":"agile","word":"Mea e mau ai (Bottleneck)","text":"O le laasaga e tasi e faaputu ai galuega ma faagesegese mea uma i tua, e pei o le ua vaapiapi o se fagu.","also":["bottleneck","bottlenecks"]},{"id":"swimlane","g":"agile","word":"Laina (Swimlane)","text":"O se laina i luga o le laupapa e faaputu ai kāte o le ituaiga e tasi, e pei o galuega faanatinati po o kāte a se 'au.","also":["swimlane","swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"O se auala e galue ai e aveese ai maumau (so'o se mea e le fesoasoani i le tagata faatau) ma faaauau ai le tafe o galuega."},{"id":"waste","g":"agile","word":"Maumau (Waste)","text":"I le Lean, so'o se mea e fai ai taumafaiga ae e le fesoasoani i le tagata faatau, e pei o le faatali, toe faia, po o le fausiaina o mea e leai se tasi e faaaoga.","noTip":1},{"id":"kaizen","g":"agile","word":"Faaleleia faaauau (Continuous improvement)","text":"O le faaleleia teisi i taimi uma e ala i suiga laiti masani, ona siaki lea pe na fesoasoani. O le retro o se auala e faia ai. E ta'ua foi o kaizen.","also":["continuous improvement","kaizen"]},{"id":"selforg","g":"agile","word":"'Au e pulea e i latou lava (Self-organising team)","text":"O se 'au e filifili e i latou lava le auala e faia ai le galuega, nai lo le taʻuina atu i laasaga taʻitasi.","also":["self-organising team","self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"'Au e tele tomai (Cross-functional team)","text":"O se 'au e iai tomai uma e manaʻomia e faamaeʻa ai le galuega e i latou lava, e pei o le mamanuina, fausiaina ma suʻega.","also":["cross-functional team","cross-functional"]},{"id":"spike","g":"agile","word":"Suʻesuʻega puʻupuʻu (Spike)","text":"O se suʻesuʻega puʻupuʻu, ua faatapulaʻa le taimi, e tali ai se fesili a o leʻi amata le galuega moni.","also":["spike","spikes"]},{"id":"rework","g":"agile","word":"Toe faia (Rework)","text":"O le toe faia o galuega ona e leʻi saʻo i le taimi muamua.","also":["rework","reworked"]},{"id":"safe","g":"agile","word":"Agile lautele (SAFe)","text":"O auala e faaaoga ai le Agile i 'au e tele i se fa'alapotopotoga tele. O le SAFe (Scaled Agile Framework) o se faataitaiga lauiloa.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"O le pusa faila o code a le poloketi ma lona talafaasolopito atoa o commit. E mafai ona i lau komepiuta, i GitHub, po o mea uma e lua.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"O se laina e ese o galuega i le code, ina ia mafai ona faia suiga e aunoa ma le paʻi i le lomiga autu.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"O se ata ua teuina o le code, faatasi ai ma se faʻamatalaga puʻupuʻu o le mea na suia. E mafai ona e toe foʻi i se tasi i so'o se taimi.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"O le auina atu o au ata ua teuina (commits) mai lenei komepiuta i le kopi faʻasoa i luga o le initoneti, e pei o GitHub, ina ia faasaoina ma mafai ona maua e isi."},{"id":"merge","g":"build","word":"Merge","text":"O le tuufaatasia o suiga mai se branch i se isi, e masani lava ona toe faafoi i le lomiga autu."},{"id":"pr","g":"build","word":"Pull request","text":"O le ole atu e siaki ma tuufaatasi suiga a se branch i le lomiga autu. O nisi uepisaite e ta'ua o se merge request.","also":["PR","PRs","merge request"]},{"id":"refactor","g":"build","word":"Refactor","text":"O le faʻamama o le code e aunoa ma le suia o mea e faia: faila laiti, igoa manino, e itiiti le toe faia."},{"id":"bug","g":"build","word":"Bug","text":"O se mea e le galue e pei ona tatau.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Iloiloga a paaga","text":"O se isi mata e toe vaai: e siaki e se tasi e ese mai i le na tusia le galuega a o leʻi oo atu iā te oe, ina ia itiiti mea sese e ui atu. I le AI-gile e siaki e se isi AI kāte taʻitasi.","also":["peer review","code review"]},{"id":"code","g":"build","word":"Code (Tusi polokalama)","text":"O faatonuga tusitusia e taʻu atu ai i se komepiuta le mea e fai. E ta'ua foi o source code.","also":["code","source code"],"noTip":1},{"id":"proglang","g":"build","word":"Gagana polokalama (Programming language)","text":"O se gagana e tusi ai code, e pei o JavaScript, Python po o Java. E fetaui gagana eseese ma galuega eseese.","also":["programming language","programming languages"]},{"id":"developer","g":"build","word":"Tagata atiaʻe (Developer, dev)","text":"O se tagata e tusi ma suia code. E ta'ua foi o se programmer po o se software engineer.","also":["developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Polokalama (Software)","text":"O polokalama e galue i luga o komepiuta ma telefoni, e ese mai i masini lava ia (le hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Puʻupuʻu mo application: o se polokalama e faʻaoga e tagata e faia ai se mea, i luga o se telefoni, se komepiuta po o se browser.","also":["app","apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"App i luga o le upega (Web app)","text":"O se app e galue i totonu o se web browser, o lea e leai se mea e tatau ona faʻapipiʻi.","also":["web app","web apps","web application"]},{"id":"frontend","g":"build","word":"Itu e vaaia (Front end)","text":"O le vaega o se app e te vaai ma kiliki i ai: o lau, o faamau ma upu, e masani i totonu o lau browser.","also":["front end","front-end","frontend"]},{"id":"backend","g":"build","word":"Itu i tua (Back end)","text":"O le vaega i tua o se app e teu ai faamatalaga ma faia galuega pe a e kiliki i se mea, e pei o le siaki o lau upu faataga.","also":["back end","back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"O le galue i le front end ma le back end uma.","also":["full stack","full-stack"]},{"id":"ui","g":"build","word":"Fesoʻotaʻiga vaaia (User interface, UI)","text":"O mea e vaai ma faʻaoga e se tagata i luga o le lau: faatulagaga, faamau, lisi ma tusitusiga.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"Lagona o le tagata faʻaoga (User experience, UX)","text":"O le lagona o le faʻaogaina o se mea: faigofie, manino ma manaia, po o le fenumiai ma lemu.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Avanoa mo tagata uma (Accessibility, a11y)","text":"O le faia o mea e mafai ona faʻaoga e tagata uma, e aofia ai ma ē le lelei le vaai, ē le mafai ona faʻaoga le isumu po o ē faʻaoga se faitau lau (screen reader).","also":["a11y","accessibility","avanoa mo tagata uma"]},{"id":"responsive","g":"build","word":"Mamanu fetuutuuna'i (Responsive design)","text":"O le faia o itulau e fetaui ma galue lelei i so'o se lapopoa o lau, mai se telefoni i se lau komepiuta tele.","also":["responsive design"]},{"id":"designsys","g":"build","word":"Faiga mamanu (Design system)","text":"O se pusa e faasoa o lanu, mataitusi, faamau ma tulafono, ina ia tutusa le foliga ma le amio o lau taʻitasi.","also":["design system","design systems"]},{"id":"architecture","g":"build","word":"Fausaga (Architecture)","text":"O le foliga atoa o se faiga: o ā vaega autu ma le auala e talanoa ai le tasi i le isi."},{"id":"database","g":"build","word":"Fale teu faamatalaga (Database, DB)","text":"O se fale teu faamatalaga ua faatulaga, e pei o se spreadsheet malosi tele e mafai e le app ona faitau ma suia.","also":["database","databases","DB"]},{"id":"schema","g":"build","word":"Faatulagaga o le database (Schema)","text":"O le faatulagaga o se database: o ā laulau o faamatalaga e iai ma le mea e tuu i ai taʻitasi.","also":["database schema","schema"]},{"id":"sql","g":"build","word":"SQL","text":"Puʻupuʻu mo structured query language: o le gagana e faʻaoga e fesili ai i le tele o database mo faamatalaga pe e suia ai.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Faamatalaga (Data)","text":"O faamatalaga e teu e se komepiuta, e pei o igoa, oka po o seti.","also":["data","dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Server (Komepiuta o auaunaga)","text":"O se komepiuta e ola pea ma tali talosaga a isi komepiuta, e pei o le auina atu o se itulau pe a e asiasi i ai.","also":["server","servers"]},{"id":"client","g":"build","word":"Client","text":"O le itu e talosaga mo se mea, e masani o lau browser po o lau app, e talanoa i se server. I pisinisi e uiga foi i se tagata faatau.","also":["client","clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Puʻupuʻu mo application programming interface: o se lisi o talosaga e mafai e se polokalama ona faia i se isi, e pei o le fesili i se auaunaga o le tau mo le valoaga o le aso nei.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"O se mea e tasi i le lisi o se API: o se tuatusi web e mafai e se polokalama ona valaʻau e maua pe auina atu ai se mea.","also":["endpoints"]},{"id":"integration","g":"build","word":"Faatasiga (Integration)","text":"O le fesootaʻia o faiga e lua ina ia galulue faatasi, e pei o lau faleoloa e auina atu oka i lau polokalama o tala tupe.","also":["integration","integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"O se feʻau e auina atu e se faiga i se isi e ia lava i le taimi lava e tupu ai se mea, e pei o le “ua maua le totogi”.","also":["webhooks"]},{"id":"library","g":"build","word":"Faletusi (Library)","text":"O code ua saunia na tusia e se isi e mafai ona e toe faaaoga nai lo le tusia e oe lava.","also":["library","libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework (Faavae)","text":"O se fausaga ua saunia mo le fausiaina o se app e filifili ai le tele o le faatulagaina o code, e pei o se faavae o se fale e te faatumuina.","also":["framework","frameworks"]},{"id":"sdk","g":"build","word":"Pusa meafaigaluega polokalama (SDK)","text":"O se pusa o meafaigaluega, code ma faataitaiga e fausia ai polokalama mo se platform po o se auaunaga e tasi.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Mea e faalagolago i ai le polokalama (Software dependency)","text":"O se faletusi (library) po o se meafaigaluega e manaʻomia e lau code ina ia galue. E taua le faafou soo o ia mea mo le saogalemu.","also":["software dependency","software dependencies"]},{"id":"package","g":"build","word":"Package (Afifi)","text":"O se afifi o code ua saunia e mafai ona e faʻapipiʻi ma faaaoga i se poloketi.","also":["package","packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Pule o package (Package manager)","text":"O se meafaigaluega e aumai ma faafou package e faalagolago i ai lau code. O le npm o se tasi e masani ai.","also":["package manager","package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"O le meafaigaluega e sili ona faaaogaina e teu ai le talafaasolopito o suiga o code, i commit ma branch."},{"id":"github","g":"build","word":"GitHub","text":"O se uepisaite e teu ai repo Git i luga o le initoneti, ina ia mafai e 'au ona faasoa code, iloilo suiga ma mataʻituina galuega."},{"id":"vcs","g":"build","word":"Pulega o lomiga (Version control)","text":"O le teuina o le talafaasolopito atoa o suiga uma i faila, ina ia e iloa ai po o ai na suia le a le mea ma mafai ona toe foʻi i tua pe a manaʻomia. E faia lea e Git.","also":["version control","source control","version control system"]},{"id":"clone","g":"build","word":"Clone (Kopi)","text":"O le faia o lau lava kopi atoa o se repo, faatasi ai ma lona talafaasolopito, i lau komepiuta.","also":["clone","cloned","cloning"]},{"id":"pull","g":"build","word":"Pull","text":"O le aumaia o commit aupito fou mai le kopi faʻasoa (e pei o GitHub) i lau komepiuta. O le faafeagai o le push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Main branch (Lala autu)","text":"O le lomiga aloaia o code e galue ai tagata uma, e masani ona ta'ua o main po o master.","also":["main branch","master branch"]},{"id":"conflict","g":"build","word":"Misa o le merge (Merge conflict)","text":"A paʻi suiga e lua i laina e tasi i auala eseese, o lea e le mafai e le komepiuta ona tuufaatasi ma e tatau i se tagata ona filifili.","also":["merge conflict","merge conflicts"]},{"id":"diff","g":"build","word":"Diff (Eseesega)","text":"O se faaaliga o le mea na suia i le va o lomiga e lua: laina na faaopoopo ma laina na aveesea.","also":["diff","diffs"]},{"id":"fork","g":"build","word":"Fork","text":"O lau lava kopi o le repo a se isi, e mafai ona e suia e aunoa ma le aʻafia o le isi.","also":["fork","forks","forked"]},{"id":"script","g":"build","word":"Script","text":"O se polokalama puʻupuʻu e faia se galuega e tasi e ia lava, e pei o le faamaopoopoina o faila po o le amataina o le app.","also":["script","scripts"],"noTip":1},{"id":"build","g":"build","word":"Build (Fausia)","text":"O le liua o le code i se mea ua sauni e faagaoioi, po o le iʻuga ua sauni lava ia e faagaoioi.","also":["build","builds"],"noTip":1},{"id":"compile","g":"build","word":"Compile","text":"O le faaliliuina o code na tusia e tagata i se foliga e mafai e le komepiuta ona faagaoioi saʻo loa.","also":["compile","compiler"]},{"id":"cli","g":"build","word":"Laina o poloaiga (CLI)","text":"O se faamalama tusitusiga e te lolomi ai faatonuga mo le komepiuta nai lo le kiliki. E ta'ua foi o le terminal.","also":["command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Faatulagaga (Configuration, config)","text":"O seti e pulea ai le amio o polokalama, e teu ese mai le code ina ia faigofie ona suia.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Environment variable","text":"O se seti e tuuina atu i se polokalama pe a amata, e masani ona faaaoga mo tuatusi po o upu faataga ina ia le tusia i totonu o le code.","also":["environment variable","environment variables","env var"]},{"id":"debugging","g":"build","word":"Suʻe mea sese (Debugging)","text":"O le suʻeina o le mafuaaga e le galue ai se mea, ma le faaleleia.","also":["debugging","debug","debugged"]},{"id":"pairing","g":"build","word":"Tusi polokalama e lua (Pair programming)","text":"E toʻalua tagata (po o se tagata ma se AI) e galulue faatasi i le code e tasi, o le tasi e lolomi ae siaki e le isi.","also":["pair programming","pairing"]},{"id":"docs","g":"build","word":"Pepa faamatalaga (Documentation, docs)","text":"O faamatalaga tusitusia o le auala e galue ai se mea po o le auala e faʻaoga ai.","also":["documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"O le faila muamua e faitau i totonu o se repo: o le a le poloketi ma le auala e amata ai.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Faiga tuai (Legacy system)","text":"O se faiga tuai o loo faaaogaina pea ae faigata ona suia, e masani lava ona ua toʻaitiiti tagata o loo malamalama pea i ai.","also":["legacy system","legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Aitalafu faatekinolosi (Technical debt)","text":"O auala puʻupuʻu e faasaoina ai le taimi nei ae faatuai ai suiga mulimuli ane, e pei o se nonogatupe e faatupu tului. O le refactoring e faaitiitia ai.","also":["technical debt","tech debt"]},{"id":"test","g":"test","word":"Test","text":"O se siaki e vaai pe galue se mea e pei ona tatau ai. O nisi suʻega e faagaoioi e le komepiuta e ia lava i taimi uma e suia ai le code; o isi o oe e taumafai i se kāte ua maeʻa a o e leʻi taliaina.","also":["tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Puʻupuʻu mo quality assurance: o mea uma e faia e mautinoa ai ua saʻo galuega a o leʻi ola. I le AI-gile o lona uiga o siaki otometi: a mumu le QA, ua le manuia se mea, ma e le mafai ona ola seʻia faaleleia.","also":["siaki o le tulaga lelei","quality assurance"]},{"id":"testpile","g":"test","word":"Faaputuga suʻega","text":"O kāte ua uma o loo faatali mo oe e taumafai ai, tasi i le tasi. Talia se tasi pe toe faafoi atu ma se faamatalaga, ona sau ai lea o le isi.","also":["test pile"]},{"id":"autotest","g":"test","word":"Suʻega otometi (Automated test)","text":"O se siaki e faagaoioi e le komepiuta e ia lava i taimi uma e suia ai le code, e maua vave ai mea sese.","also":["automated test","automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Suʻega i lima (Manual test)","text":"O se tagata e taumafai i le galuega i ona lava lima e vaai pe amio e pei ona tatau.","also":["manual test","manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Unit test","text":"O se siaki otometi laʻitiiti o se fasi code e tasi na o ia.","also":["unit tests"]},{"id":"integtest","g":"test","word":"Suʻega o le faatasiga (Integration test)","text":"O se siaki e galue lelei vaega e tele faatasi, e le na o le tasi i le taimi.","also":["integration test","integration tests"]},{"id":"endtoend","g":"test","word":"Suʻega mai le amataga i le iʻuga (E2E)","text":"O se suʻega e amio e pei o se tagata faʻaoga moni mai le amataga seʻia iʻu, e pei o le lesitala, faatau ma totogi.","also":["E2E","end-to-end test","end-to-end tests"]},{"id":"uat","g":"test","word":"Suʻega taliaina a tagata faʻaoga (UAT)","text":"O tagata na ole mai le galuega e taumafai i ai e i latou lava ma taʻu mai pe faia le mea latou te manaʻomia. O le faaputuga Mo oe a le AI-gile o lona ituaiga lea.","also":["UAT","acceptance testing"]},{"id":"regression","g":"test","word":"Toe faaleaga (Regression)","text":"O se mea sa galue ae ua malepe ina ua suia. E siaki e suʻega regression pe galue pea mea tuai.","also":["regression","regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Smoke test (Suʻega vave)","text":"O se siaki vave tele pe galue mea autu, mo se faataitaiga i le taimi lava ua ola ai se suiga. A le pasi, taofi ma vaai.","also":["smoke test","smoke tests"]},{"id":"exploratory","g":"test","word":"Suʻega suʻesuʻe (Exploratory testing)","text":"O le taumafai saoloto i le oloa ma le tofotofo i auala eseese, e maua ai faafitauli e misi i siaki ua fuafuaina.","also":["exploratory testing","exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Mataupu suʻega (Test case)","text":"O se tulaga tusitusia e tasi e taumafai ai: o laasaga, ma le mea e tatau ona tupu.","also":["test case","test cases"]},{"id":"coverage","g":"test","word":"Aofaʻi o le code ua suʻeina (Test coverage)","text":"O le tele o le code ua siakina e suʻega otometi. E masani ona saogalemu atu pe a tele, ae e le faamaonia e le aofaʻi tele na o ia ua lelei le galue.","also":["test coverage","code coverage"]},{"id":"testdata","g":"test","word":"Faamatalaga suʻega (Test data)","text":"O faamatalaga faataitaiga ua fatu e faaaoga a o faia suʻega, ina ia aua nei aliali ai mea lilo o se tagata moni.","also":["test data","test fixtures"]},{"id":"edgecase","g":"test","word":"Tulaga tuaoi (Edge case)","text":"O se tulaga e le masani i le tapulaʻa, e pei o se fomu gaogao po o se igoa e iai se apostrophe, lea e masani ona malepe ai mea.","also":["edge case","edge cases"]},{"id":"happypath","g":"test","word":"Ala fiafia (Happy path)","text":"O le ala masani e lelei ai mea uma. E taumafai foi le suʻega lelei i ala e le fiafia."},{"id":"perftest","g":"test","word":"Suʻega o le saosaoa (Performance testing)","text":"O le siakiina pe faapefea le saoasaoa o se mea ma pe lelei lona onosai pe a mamafa le uta.","also":["performance testing","performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Suʻega o le uta (Load testing)","text":"O le siakiina pe fefea ona onosaia e se faiga pe a faaaoga e le tele o tagata i le taimi e tasi.","also":["load testing","load test","load tests"]},{"id":"sectest","g":"test","word":"Suʻega o le saogalemu (Security testing)","text":"O le suʻesuʻeina o vaivaiga e mafai ona faataga ai se tasi e faaaoga sese se faiga pe vaai i mea e le tatau ona ia vaai i ai.","also":["security testing","security test","security tests"]},{"id":"accesstest","g":"test","word":"Suʻega o le avanoa mo tagata uma (Accessibility testing)","text":"O le siakiina e mafai e tagata e eseese o latou malosi ona faaaoga le oloa, e aofia ai ma se faitau lau (screen reader) po o se keyboard na o ia.","also":["accessibility testing","accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"O se siaki otometi e iloa ai mea sese e foliga mai ma tusitusiga le mamā i code, e pei o se siaki sipelaga mo polokalama.","also":["linter","lint"]},{"id":"static","g":"test","word":"Iloiloga static (Static analysis)","text":"O le siakiina o code mo faafitauli e ala i le faitauina otometi, e aunoa ma le faagaoioia.","also":["static analysis","static code analysis"]},{"id":"flaky","g":"test","word":"Suʻega le mautu (Flaky test)","text":"O se suʻega e pasi i nisi taimi ae le pasi i nisi taimi e aunoa ma se mafuaaga manino, o lea e le mafai ona talitonuina atoa.","also":["flaky test","flaky tests"]},{"id":"repro","g":"test","word":"Toe faatupu (Reproduce, repro)","text":"O le faatupu ma le loto o se bug ina ia toe tupu, e ala i le mulimuli i laasaga lava ia e tasi, ina ia mafai ona suʻesuʻe ma faaleleia. O le tusiina o na laasaga o le vaega sili ona aoga o se lipoti o le bug.","also":["repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Mamafa (Severity)","text":"O le leaga o le aafiaga o se faafitauli, mai se mea laʻitiiti e faalavelave seʻia taofia mea uma.","also":["severity","severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"O le kopiina o se lomiga fou o le polokalama i komepiuta e faagaoioi ai, e pei o se kopi suʻega po o le auaunaga ola."},{"id":"release","g":"change","word":"Lomiga","text":"O se fusi ua faaigoaina o galuega ua uma e ola faatasi, faatasi ai ma ni faamatalaga puupuu o mea na suia. E tusia e 🚀 Lomiga ia faamatalaga mai kāte ua uma.","also":["lomiga fou","release","releases"]},{"id":"rollback","g":"change","word":"Toe faafoi","text":"O le toe foʻi i le lomiga mulimuli na galue pe a faalavelave se mea fou. I le AI-gile, o le Toe faafoi e aoina ai laasaga e toe faaleaogaina ua tusia i suiga taʻitasi i se lisi e tasi.","also":["rollback","roll back","ua toe faafoi"]},{"id":"live","g":"change","word":"Ola","text":"O le lomiga moni e faʻaaogaina e tagata, e ese mai i se kopi e taumafai ai mea. E taʻua foʻi e le au atiaʻe o le production.","also":["live","production"],"noTip":1},{"id":"change","g":"change","word":"Suiga","text":"O se suiga ua fuafuaina i se mea e faalagolago i ai tagata, e tusia muamua: o le a, aisea, le lamatiaga, afea, ma le auala e toe faaleaogaina ai. Amata i le 🔀 Talosaga se suiga.","also":["suiga","talosaga mo se suiga","change"],"noTip":1},{"id":"risk","g":"change","word":"Lamatiaga","text":"O se mea e ono sese, ua fuaina i le avanoa e tupu ai ma le leaga pe a tupu. E teuina e ⚠️ Lamatiaga i se lisi e tasi, o le togi maualuga muamua, e taʻitasi ma se aso e toe vaai ai.","also":["lamatiaga","risk","risks"]},{"id":"chgwin","g":"change","word":"Faamalama o suiga","text":"O taimi e mafai ai ona ola suiga, e pei o se afiafi filemu o le Aso Lua. I fafo atu o se faamalama, e le mafai ona faauma se kāte suiga, vagana ua faafuaseʻi.","also":["faamalama o suiga","change window"]},{"id":"gonogo","g":"change","word":"Alu / aua le alu","text":"O se siaki mulimuli a o leʻi ola se suiga: e fai mai tagata taʻitasi e tatau ona faatagaina, Alu po o Aua le alu. E agaʻi i luma na o le taimi e fai mai uma ai tagata Alu.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Faatagaga","text":"O le faatali mo se ioe a o leʻi amata le galuega. O se kāte e talosagaina e se uo, po o se suiga, e faatali i ✅ Faatagaga seʻia e talia pe teena.","also":["faatagaga","approval"]},{"id":"quiettime","g":"change","word":"Taimi filemu","text":"O se vaitaimi, e pei o le taimi o se live stream, se faaaliga po o le po, e leai ai se mea e ola. E faaauau pea e 'au ona galue ma suʻe, ae e faatali le ola seʻia uma. I isi nofoaga e ta'ua o se change freeze.","also":["taimi filemu","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"O se auala e galue ai e galulue ai tagata e fausia polokalama ma tagata e faagaoioia o se 'au e tasi, faatasi ai ma le tele o otometi, ina ia ola suiga soo ma le saogalemu."},{"id":"cicd","g":"change","word":"CI/CD (tuufaatasia ma momoli faaauau)","text":"E tuufaatasia soo suiga a tagata uma i le lomiga autu ma siakina otometi i taimi uma (continuous integration), ina ia sauni pea le polokalama e ola i le oomiga o se faamau (continuous delivery).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Faaolaina faaauau (Continuous deployment)","text":"O se laasaga sili atu nai lo le continuous delivery: o suiga uma e pasi siaki e ola e ia lava, e leai se faamau e oomi.","also":["continuous deployment","continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline (Alaasu)","text":"O le faasologa otometi o laasaga e ui ai se suiga i lona ala e ola ai, e pei o le build, suʻega, ona deploy lea.","also":["pipeline","pipelines"]},{"id":"environment","g":"change","word":"Siosiomaga (Environment)","text":"O se kopi ese o le faiga mo se faamoemoe e tasi, e pei o se tasi e fausia ai, se tasi e suʻe ai ma le tasi o loo ola (live).","also":["environment","environments"],"noTip":1},{"id":"devenv","g":"change","word":"Siosiomaga e atiaʻe ai (Development environment)","text":"O le kopi e galue ai se tagata atiaʻe, e masani i lana lava komepiuta, lea e leai se tasi e afaina pe a malepe mea.","also":["development environment","dev environment"]},{"id":"testenv","g":"change","word":"Siosiomaga mo suʻega (Test environment)","text":"O se kopi ese o le faiga e faaaoga na o suʻega, ina ia aua nei paʻia le auaunaga moni.","also":["test environment","test environments"]},{"id":"staging","g":"change","word":"Staging","text":"O se kopi mulimuli ua faatulaga e pei lava o le faiga ola, mo se siaki mulimuli a o leʻi ola se suiga.","also":["staging environment"]},{"id":"artifact","g":"change","word":"Build artifact (Mea na fausia)","text":"O le faila po o le afifi e maua mai i le build, ua sauni e teu, siaki pe faaola.","also":["build artifact","build artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix (Faaleleiga vave)","text":"O se faaleleiga faanatinati e faaola vave, i fafo o le fuafuaga masani, ona ua malepe se mea taua.","also":["hotfix","hotfixes"]},{"id":"patch","g":"change","word":"Patch (Faaleleiga laʻitiiti)","text":"O se faafouga laʻitiiti e faaleleia ai se bug pe tapuni ai se pu o le saogalemu. E taua le faaaoga vave o patch saogalemu.","also":["patch","patches","security patch","security patches"]},{"id":"version","g":"change","word":"Numera o le lomiga (Version number)","text":"O se igoa e pei o le 2.4.1 e taʻu mai ai po o le fea lomiga o iai. E masani ona suia le numera muamua mo suiga tetele ma le mulimuli mo faaleleiga laiti.","also":["version number","version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Tusi o suiga o le lomiga (Release notes)","text":"O se lisi puʻupuʻu faigofie o mea na suia i se lomiga, mo tagata e faʻaoga, e aofia ai faaleleiga ma tapulaʻa ua iloa. E ta'ua foi o se changelog.","also":["release notes","changelog","change log"]},{"id":"flag","g":"change","word":"Fa'ailoga o le gaoioiga (Feature flag)","text":"O se faamau tatala ma tape mo se gaoioiga, ina ia mafai ona ola galuega fou a o natia, ona faaola lea (po o le toe tape) e aunoa ma se lomiga fou.","also":["feature flag","feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Agaʻi i luma (Roll forward)","text":"O le faaleleia o se lomiga leaga e ala i le vave tuuina atu o se lomiga fou ua faasaʻo, nai lo le toe foʻi i le tuai.","also":["roll forward","rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Canary release (Lomiga muamua i nai tagata)","text":"O le faaolaina o se suiga mo se vaega laʻitiiti muamua, ma mo tagata uma pe a manino ua lelei. Na faaigoa i manulele canary na ave e tagata eli i lalo o le eleele e fai ma lapataiga muamua.","also":["canary release","canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Blue-green deployment","text":"O le teuina o kopi e lua o le faiga ola ma le sui o tagata uma i le fou i le taimi e tasi, ina ia mafai ona toe sui vave i tua pe a iai se mea e sese.","also":["blue-green","blue green deployment","blue-green deployment"]},{"id":"zerodown","g":"change","word":"Faaolaina e aunoa ma se taofi (Zero-downtime deployment)","text":"O le faaolaina o se lomiga fou e aunoa ma le taofia lava o le auaunaga mo ona tagata.","also":["zero downtime","zero-downtime","zero-downtime deployment"]},{"id":"chgenable","g":"change","word":"Fesoasoani i suiga (Change enablement)","text":"O le fesoasoani ina ia manuia suiga: fuaina o le lamatiaga, maua o le faatagaga saʻo ma filifili o se taimi lelei. E ta'ua foi o change management.","also":["change enablement","change management"]},{"id":"cab","g":"change","word":"Komiti fautuaga o suiga (CAB)","text":"O se vaega e iloilo suiga taua ma malilie pe mafai ona faaauau ma po o afea.","also":["CAB","change advisory board"]},{"id":"stdchange","g":"change","word":"Suiga masani (Standard change)","text":"O se suiga e maualalo lona lamatiaga e faia i taimi uma i le auala lava e tasi ua faamaonia, o lea ua faatagaina muamua.","also":["standard change","standard changes"]},{"id":"normchange","g":"change","word":"Suiga lautele (Normal change)","text":"O se suiga e tatau ona siaki ma faatagaina a o leʻi faia.","also":["normal change","normal changes"]},{"id":"emergchange","g":"change","word":"Suiga faanatinati (Emergency change)","text":"O se suiga e tatau ona faia i le taimi lava lea e faaleleia pe taofia ai se faafitauli tele, faatasi ai ma se faatagaga vave e fetaui.","also":["emergency change","emergency changes"]},{"id":"automation","g":"change","word":"Otometi (Automation)","text":"O le faataga o le komepiuta e faia e ia lava se galuega e toe fai soo, ina ia vave ma faia i le auala e tasi i taimi uma.","also":["automation","automated"],"noTip":1},{"id":"infra","g":"change","word":"Meafaigaluega autu (Infrastructure)","text":"O masini, feso'ota'iga ma auaunaga e faagaoioi ai polokalama.","also":["infrastructure","infra"]},{"id":"iac","g":"change","word":"Infrastructure as code (IaC)","text":"O le faamatalaina o au server ma seti i faila e teu faatasi ma le code, ina ia mafai ona toe fausia i le auala e tasi i taimi uma.","also":["IaC","infrastructure as code"]},{"id":"cloud","g":"change","word":"Cloud (Ao)","text":"O le mautotogi o komepiuta, nofoaga e teu ai mea ma auaunaga mai se kamupani tele i luga o le initoneti, nai lo le umia o masini e oe lava.","also":["cloud","the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Kamupani o le cloud (Cloud provider)","text":"O se kamupani e faamautotogi atu komepiuta i luga o le initoneti, e pei o Amazon Web Services (AWS), Microsoft Azure po o Google Cloud.","also":["cloud provider","cloud providers"]},{"id":"hosting","g":"change","word":"Hosting (Nofoaga i luga o le initoneti)","text":"O le mea e nofo ai ma galue ai lau app po o lau uepisaite ina ia mafai e tagata ona oo atu i ai, e masani ona mautotogi mai se kamupani.","also":["hosting"]},{"id":"domain","g":"change","word":"Igoa o le domain (Domain name)","text":"O le tuatusi web e lolomi e tagata, e pei o example.com. E mautotogi i tausaga taʻitasi, o lea e tatau ona toe faafouina.","also":["domain name","domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Puʻupuʻu mo domain name system: o le tusi tuatusi o le initoneti, e liua ai se igoa e pei o example.com i le tuatusi o le komepiuta saʻo.","also":["domain name system"]},{"id":"container","g":"change","word":"Container (Pusa)","text":"O se afifi ua tapuni malu o loʻo i ai se app ma mea uma e manaʻomia, ina ia galue tutusa i so'o se komepiuta. O le Docker le meafaigaluega sili ona lauiloa.","also":["container","containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Komepiuta faafoliga (Virtual machine, VM)","text":"O se komepiuta faafoliga e galue i totonu o se komepiuta moni, ina ia mafai e se masini tele ona galue e pei o ni komepiuta e tele.","also":["VM","VMs","virtual machine","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"O le faagaoioia o code e aunoa ma le tausia e oe o ni server: e faagaoioi e le kamupani pe a manaʻomia ma e totogi na o le mea e te faʻaoga."},{"id":"lb","g":"change","word":"Tufa uta (Load balancer)","text":"O se mea e tufa ai tagata asiasi i server e tele, ina ia aua nei lofituina se tasi.","also":["load balancer","load balancers"]},{"id":"cache","g":"change","word":"Cache","text":"O se fale teu faigofie o iʻuga talu ai nei e teu latalata, ina ia aua nei toe aumaia pe toe fuafuaina le mea e tasi. O le faamamāina e mafai ona faaleleia ai itulau e foliga tuai.","also":["cache","caches","caching","cached"]},{"id":"cdn","g":"change","word":"Feso'ota'iga tufa (CDN)","text":"O se seti o server i le lalolagi atoa e teu ai kopi o au itulau ma ata latalata i tagata asiasi, ina ia vave ona aliali mai.","also":["CDN","content delivery network"]},{"id":"migration","g":"change","word":"Siitia (Migration)","text":"O le siitia o faamatalaga po o faiga mai se faatulagaga tuai i se mea fou, po o le suia ma le faaeteete o le faatulagaga o se database.","also":["migration","migrations","database migration"]},{"id":"service","g":"run","word":"Auaunaga","text":"O se mea na e fausia e faalagolago i ai tagata, e pei o se upegatafaʻilagi po o se app, e tausia ina ia aoga pea. Faailoga le “O lenei poloketi o se auaunaga” ma taʻu le mea e ofo atu, o ai e faʻaaogaina, ma o ai o loo i le tiute.","also":["auaunaga","service"]},{"id":"uptimepct","g":"run","word":"Taimi ola (Uptime)","text":"O le tele o taimi e galue ai se auaunaga, e masani o se pasene. O le 99.9% e faatagaina pea le tusa ma le 43 minute i le masina e le galue ai.","also":["uptime","uptime percentage"]},{"id":"uptime","g":"run","word":"Siaki o le ola","text":"O se siaki otometi, i minute nai taʻitasi, pe o tali mai pea lau auaunaga. Afai e toilalo faafaasolo ni nai taimi, e tatala e le AI-gile lava ia se kāte o se mea ua tupu.","also":["uptime checks","siaki o le ola"]},{"id":"statuspage","g":"run","word":"Itulau o le tulaga","text":"O se itulau lautele e faaali ai pe o aoga se auaunaga (lanu meamata, moli po o le mumu) ma le tala fou lata mai, ina ia mafai e tagata e faʻaaogaina ona siaki nai lo le fesili.","also":["status page"]},{"id":"desk","g":"run","word":"Laulau auaunaga","text":"O le nofoaga e oo mai ai fesili ma lipoti mai tagata o loʻo faʻaaogaina lau auaunaga. E faavasega e AI-gile taʻitasi o se talosaga, o se mea ua tupu po o se manatu, ma faʻailoa atu pe a foliga e pei o se mea ua uma ona lipotia.","also":["laulau","help desk","helpdesk","service desk"]},{"id":"svcrequest","g":"run","word":"Talosaga mo auaunaga","text":"Pe a talosaga se tasi mo se mea masani, e pei o se faʻamaumauga fou po o sina fesoasoani, nai lo le lipotia o se mea ua malepe. E faatali i lona taimi; e muamua le mea ua tupu.","also":["talosaga","service request"]},{"id":"incident","g":"run","word":"Mea ua tupu","text":"O se mea ua malepe pe le galue lelei mo tagata o loo faaaoga i le taimi nei, e pei o le uepisaite ua pau po o le lemu tele. O se kāte 🔥 mea ua tupu e muamua i le laina: o le toe faagaoioia lelei e muamua.","also":["faalavelave","incident"]},{"id":"major","g":"run","word":"Mea ua tupu tele","text":"O se mea ua tupu tele: e toʻatele tagata ua aʻafia, po o tupe po o faamaumauga ua lamatia. E tasi le faamau e tuʻu ai ʻau uma i ai (fuifui), fafagu le tagata o loo i le tiute, ma talosaga mo se tala fou o le tulaga i minute e 30 taʻitasi.","also":["faalavelave tele","major incident"]},{"id":"oncall","g":"run","word":"I le tiute","text":"O le avea ma tagata e tali pe a malepe se mea, e oo lava i le po. O auaunaga taʻitasi e iai se sui o le ʻau o loo i le tiute e fafagu muamua mo ona mea ua tutupu.","also":["on call","on-call"]},{"id":"replyby","g":"run","word":"Taimi o tali","text":"Le umi e mafai ai e se kāte ona faatali mo se tali muamua, mo se faataʻitaʻiga e tasi le itula mo se mea ua tupu. A uma lea e maua ai se uati mumu, ina ia leai se mea e galo filemu. E taʻua foʻi o le taimi faatulagaina o tali.","also":["taimi o tali","response target"]},{"id":"postmortem","g":"run","word":"Iloiloga pe a uma","text":"O se toe tilotilo puupuu pe a uma se mea ua tupu: o le mea na tupu, o le mea na fesoasoani, ma le mea e suia, e aunoa ma le tuuaʻia o se tasi. E le mafai ona tapunia se mea ua tupu e aunoa ma se tasi.","also":["post-mortem","postmortem"]},{"id":"problem","g":"run","word":"Faʻafitauli","text":"O le mafuaaga lilo i tua o se tasi pe sili atu mea ua tutupu. E faapotopoto e se kāte 🧩 faʻafitauli mea ua tutupu e toe foʻi mai pea, ina ia maua le mafuaaga ma faasaʻo e faavavau.","also":["faafitauli","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Mafuaaga autu","text":"O le mafuaaga moni na malepe ai se mea, ae le na o le mea na e vaaia ua sese. Faasaʻo le mafuaaga autu ona le toe foʻi mai lea o le mea ua tupu.","also":["root cause"]},{"id":"workaround","g":"run","word":"Fofo mo le taimi nei","text":"O se auala e aoga pea ai mea seʻia sauni le faasaʻoga moni, e pei o le toe amataina o se mea pe a mau. E tusia i le kāte faʻafitauli ina ia le toe sailia e se tasi.","also":["workaround"]},{"id":"knownerror","g":"run","word":"Mea sese ua iloa","text":"O se faafitauli ua malamalama i lona mafuaaga ae e leʻi faaleleia, e masani ona iai se fofo mo le taimi nei ua tusia. O le 🧩 Mea sese ua iloa e lisi ai, ina ia faaaoga e tagata uma le fofo nai lo le toe eli.","also":["known error","known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"O faatonuga laasaga ma laasaga e faasaʻo ai se ituaiga faʻafitauli ua iloa, ina ia faia i le auala lava e tasi, vave, i taimi uma. A uma se mea ua tupu tele, e mafai e le ʻau ona fautuaina se tasi mo lau ioe.","also":["runbooks"]},{"id":"ci","g":"run","word":"Mea faatulagaina","text":"O se mea e tasi e faalagolago i ai lau auaunaga, e pei o se server, se domain, se tusi faamaonia, se ki po o se kamupani e tuʻuina mai mea. O le 🗂️ Mea faatulagaina e lisi ai i latou mo auaunaga taʻitasi, ina ia e iloa le mea e aafia i se mea ua tupu ma le mea e manaʻomia ona faʻafouina pe faʻasao se kopi.","also":["mea faatulagaina","configuration item"]},{"id":"expiry","g":"run","word":"Aso e uma ai","text":"O le aso e le toe galue ai se mea seʻi vagana ua toe faafouina, e pei o le tusi faamaonia o le saogalemu o se uepisaite po o lona tuatusi web. E mataʻituina e le AI-gile nei aso ma faia ai se kāte e tasi e toe faafou ai mea taʻitasi i aso e 30 muamua, ina ia le taofi faafuasei se mea.","also":["aso e uma ai","uma le taimi","expiry"]},{"id":"backup","g":"run","word":"Kopi faasao","text":"O se kopi ua teuina o au faamaumauga mai muamua, e toe faalagolago i ai pe a leiloa pe faaleagaina se mea. E faia e le AI-gile se kopi faasao o au laupapa i aso uma.","also":["backup","backups"]},{"id":"restore","g":"run","word":"Toe aumai","text":"O le toe tuʻuina mai o faamaumauga mai se kopi faasao. E moni lava le aoga o se kopi faasao pe a e iloa e mafai ona toe aumai, o lea e lelei ona taumafai i lea taimi ma lea taimi.","also":["restore","toe faafoi mai"]},{"id":"svcreview","g":"run","word":"Iloiloga o le auaunaga","text":"O se toe tilotilo i le masina e tasi o se auaunaga: mea ua tupu na tatala ma faasaʻo, le vave o le maua e tagata o se tali, le taimi na ola ai ma tokena na faʻaaogaina. E faʻaali e le Iloiloga o le masina lenei mea mo auaunaga taʻitasi.","also":["iloiloga o le masina","service review"]},{"id":"accessreview","g":"run","word":"Iloiloga o le ulufale","text":"O le siakiina i aso e 90 taʻitasi po o ai o loo mafai pea ona ulufale: so'otaga e faasoa, tofiga a uo ma upu faataga ma ki ua teuina. E teu pe aveese e oe taʻitasi, ina ia aua nei tumau le ulufale tuai.","also":["access review"]},{"id":"improvements","g":"run","word":"Lisi o faaleleiga","text":"O mea uma na filifili le ʻau e faalelei atili, i se nofoaga e tasi: fautuaga mai le toe iloilo, galuega mai iloiloga ma faasaʻoga o faʻafitauli, taʻitasi ma lona tulaga. Saili i le 📈 Faaleleiga.","also":["faaleleiga","improvements"]},{"id":"tokencap","g":"run","word":"Tapulaa tokena","text":"O se tapulaa i le masina mo tokena e mafai ona faʻaaoga e sooupu o se auaunaga. I le 80% e te maua ai se lapataiga; i le 100% e faatali a latou galuega i tua seia oo i le masina fou pe seia e siitia le tapulaa.","also":["tapulaa token","token cap"]},{"id":"svcmgmt","g":"run","word":"Pulega o auaunaga (Service management)","text":"O mea uma e aofia i le tausia o se auaunaga e aoga ma galue mo tagata e faalagolago i ai, aso uma.","also":["service management"]},{"id":"itil","g":"run","word":"ITIL","text":"O se taiala e faaaoga lautele mo le lelei o le pulega o auaunaga, e aofia ai mea e pei o mea ua tupu, faafitauli ma suiga. O le igoa sa uiga i le IT Infrastructure Library."},{"id":"itsm","g":"run","word":"Pulega o auaunaga IT (ITSM)","text":"O le faagaoioia o tekinolosi o se auaunaga mo tagata, ma ni auala manino e taulimaina ai talosaga, mea ua tupu, suiga ma faaleleiga.","also":["ITSM","IT service management"]},{"id":"managed","g":"run","word":"Auaunaga ua pulea (Managed service)","text":"O se auaunaga e faagaoioia ma tausia e se isi mo oe, i lalo o se maliega i le lelei e tatau ona galue ai.","also":["managed service","managed services"]},{"id":"svcowner","g":"run","word":"Pule o le auaunaga (Service owner)","text":"O le tagata e tali mo se auaunaga atoa: le lelei o lona galue, lona tau ma le auala e faaleleia ai.","also":["service owner","service owners"]},{"id":"sla","g":"run","word":"Maliega o le tulaga o auaunaga (SLA)","text":"O se folafolaga tusitusia i tagata faatau i le lelei e galue ai se auaunaga, e pei o le “ola i le 99.9% o le taimi” po o le “tali i totonu o le itula e tasi”, e masani ona iai se toe foʻi o tupe pe a le faataunuʻuina.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Sini o le tulaga o auaunaga (SLO)","text":"O le sini a le 'au lava mo le lelei e tatau ona galue ai se auaunaga i se vaitaimi, e masani ona seti maualuga teisi nai lo le SLA mo le saogalemu.","also":["SLO","SLOs","service level objective"]},{"id":"sli","g":"run","word":"Fua o le tulaga o auaunaga (SLI)","text":"O le fuaga moni e te siaki faasaga i se sini, e pei o le vaega o asiasiga na aliali lelei mai ai le itulau.","also":["SLI","SLIs","service level indicator"]},{"id":"availability","g":"run","word":"Maua (Availability)","text":"Pe mafai e tagata ona faʻaoga se auaunaga pe a latou manaʻomia, e masani ona fuaina o le uptime.","also":["availability","high availability"]},{"id":"downtime","g":"run","word":"Taimi e le galue ai (Downtime)","text":"O le taimi e le galue ai se auaunaga pe tape, ua fuafuaina pe leai.","also":["downtime","down time"]},{"id":"errorbudget","g":"run","word":"Fua o mea sese e faatagaina (Error budget)","text":"O le aofaʻi laʻitiiti o le le manuia e faatagaina e lau sini o le mautu. A o iai pea se vaega o totoe, e mafai ona e fai suiga e iai lamatiaga; a uma, e tatau ona e faagesegese.","also":["error budget","error budgets"]},{"id":"outage","g":"run","word":"Motusia o le auaunaga (Outage)","text":"O se taimi e motusia ai se auaunaga pe malepe tele mo ona tagata.","also":["outage","outages"]},{"id":"degraded","g":"run","word":"Le lelei (Degraded)","text":"E galue, ae leaga: e lemu, pe o isi vaega e le galue.","also":["degraded","degraded service"]},{"id":"monitoring","g":"run","word":"Mataʻituina (Monitoring)","text":"O le mataʻituina otometi o se auaunaga i taimi uma, ina ia iloa faafitauli, e sili a o leʻi iloa e tagata faʻaoga.","also":["monitoring"]},{"id":"observability","g":"run","word":"Mafai ona vaai atu (Observability)","text":"O le lelei o lou mafai ona iloa le mea o tupu i totonu o se faiga mai fafo, e faaaoga ai ana log, numera ma trace.","also":["observability","o11y"]},{"id":"log","g":"run","word":"Log (Faamaumauga)","text":"O se api o aso e tusi pea e se polokalama o mea o loo faia, e faaaoga e iloa ai le mea na sese.","also":["log","logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Trace (Sailiga o le ala)","text":"O se faamaumauga o le auala e malaga ai se talosaga e tasi i vaega ese o se faiga, laasaga i laasaga, e faaali ai le mea na faatuai ai.","also":["trace","traces","tracing"]},{"id":"latency","g":"run","word":"Faatuai (Latency)","text":"O le umi e alu ai se mea e tali, e pei o le faatali i le va o le kiliki ma le aliali mai o le itulau.","also":["latency"]},{"id":"alert","g":"run","word":"Lapataiga (Alert)","text":"O se feʻau otometi e iai se mea e manaʻomia le gauai atu i ai, e pei o le uepisaite e le tali.","also":["alert","alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Fiu i lapataiga (Alert fatigue)","text":"A tele naua lapataiga ma amata ona le amanaiaina e tagata, e aofia ai ma lapataiga taua.","also":["alert fatigue","alarm fatigue"]},{"id":"dashboard","g":"run","word":"Dashboard (Laupapa o faamatalaga)","text":"O se lau e faaali ai numera ma tulaga sili ona taua i se vaai e tasi.","also":["dashboard","dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Valaʻau faanatinati (Paging)","text":"O le valaʻau faanatinati pe faaala le tagata i le tiute e uiga i se faafitauli.","also":["paging","paged"]},{"id":"escalation","g":"run","word":"Siitia i luga (Escalation)","text":"O le aumaia o se tagata e sili atu lona tomai po o lana pule pe a le mafai ona foia se mataupu i le tulaga o iai nei, pe le lava le vave.","also":["escalation","escalate","escalated"]},{"id":"triage","g":"run","word":"Triage (Faavasegaina)","text":"O le vave faavasegaina o mataupu o sau e tusa ai ma le faanatinati ma le taua, ina ia muamua taulimaina mea sili ona leaga.","also":["triage","triaged"]},{"id":"impact","g":"run","word":"Aafiaga (Impact)","text":"O le tele o le aafia o tagata i se mea: pe toʻafia, ma le mamafa o le aafiaga.","noTip":1},{"id":"urgency","g":"run","word":"Faanatinati (Urgency)","text":"Le vave e tatau ona taulimaina ai se mea. O le aafiaga ma le faanatinati faatasi e seti ai le faamuamua.","noTip":1},{"id":"plevels","g":"run","word":"Tulaga faamuamua (P1, P2…)","text":"O igoa e faailoa ai le faanatinati o se mataupu. O le P1 o le sili ona mamafa ma e manaʻomia ai se gaoioiga i le taimi lava lea.","also":["priority levels","P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Laina o tikete (Ticket queue)","text":"O le lisi o talosaga ma mea ua tupu o loo faatali e ave.","also":["ticket queue","ticket queues"]},{"id":"tiers","g":"run","word":"Laina muamua ma laina lua","text":"O tulaga o le lagolago: o le laina muamua e talia le valaʻau ma faaleleia mea faigofie; o le laina lua e iai tomai loloto mo mea e sili atu ona faigata. E ta'ua foi o tier 1 ma tier 2.","also":["first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Taʻitaʻi o mea ua tupu (Incident commander)","text":"O le tagata e tasi e taʻitaʻia le tali i se mea ua tupu, ina ia iloa e tagata uma po o ai e filifili ma po o ai e faia le a le mea.","also":["incident commander","incident commanders"]},{"id":"responsetime","g":"run","word":"Taimi e tali ai (Response time)","text":"O le umi seʻia muamua ave e se tasi se talosaga po o se mea ua tupu.","also":["response time","response times"]},{"id":"resolution","g":"run","word":"Taimi e foia ai (Resolution time)","text":"O le umi e alu ai e foia atoatoa se talosaga po o se mea ua tupu, mai le lipoti seʻia faaleleia.","also":["resolution time","resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Taimi ogatotonu e toe faaleleia ai (MTTR)","text":"I le averesi, o le umi e alu ai e toe galue se auaunaga pe a malepe. E mafai ona sina eseese uiga o le MTTR, o lea ia taʻu manino le mea e te fuaina.","also":["MTTR","mean time to recover","mean time to restore"]},{"id":"mtbf","g":"run","word":"Taimi ogatotonu i le va o malepe (MTBF)","text":"I le averesi, o le umi e galue ai se auaunaga a o leʻi malepe se mea.","also":["MTBF","mean time between failures"]},{"id":"cmdb","g":"run","word":"Database o mea faatulagaina (CMDB)","text":"O le lisi o mea faatulagaina uma ma le auala e fesootai ai, ina ia e vaai po o le a le mea e faalagolago i le isi.","also":["CMDB","configuration management database"]},{"id":"asset","g":"run","word":"Meatotino (Asset)","text":"So'o se mea tāua o loo e umia po o loo e totogi e faagaoioia ai le auaunaga, e pei o se komepiuta feaveaʻi, o se laisene polokalama po o se domain.","also":["asset","assets"],"noTip":1},{"id":"capplan","g":"run","word":"Fuafuaga o le malosi (Capacity planning)","text":"O le mautinoa o le a lava le malosi o komepiuta, nofoaga e teu ai mea ma tagata mo mea o sau.","also":["capacity planning","capacity plan"]},{"id":"scaling","g":"run","word":"Faateleina (Scaling)","text":"O le taulimaina o le toʻatele atu o tagata faʻaoga e ala i le tuuina atu o se masini e sili atu lona malosi (scaling up) po o le faaopoopoina o isi masini (scaling out).","also":["scaling","scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Faaauauina o pisinisi (Business continuity)","text":"O fuafuaga e faaauau ai mea taua pe a tupu se mea tele, e pei o le leiloa o se ofisa, o se kamupani autu e tuʻuina mai mea po o komepiuta.","also":["business continuity","business continuity plan"]},{"id":"dr","g":"run","word":"Toe faaleleia pe a mavae se mala (DR)","text":"O le fuafuaga ma meafaigaluega e toe maua ai se auaunaga pe a mavae se mea tele, e pei o le leiloa o se fale atoa o server (data centre).","also":["DR","disaster recovery"]},{"id":"rto","g":"run","word":"Taimi sili e toe faaleleia ai (RTO)","text":"O le taimi sili ona umi e mafai ona le galue ai se auaunaga pe a mavae se mala, a o leʻi tatau ona toe galue.","also":["RTO","recovery time objective"]},{"id":"rpo","g":"run","word":"Sini o faamatalaga e mafai ona leiloa (RPO)","text":"O le tele o faamatalaga fou e mafai ona e leiloa, e fuaina i le taimi. O le RPO e tasi le itula, o lona uiga e tatau ona faia kopi faasao (backups) i itula taʻitasi pe soo atu.","also":["RPO","recovery point objective"]},{"id":"redundancy","g":"run","word":"Mea e sui (Redundancy)","text":"O le iai o mea e sui ua sauni, e pei o se server lona lua, ina ia aua nei taofia le auaunaga i se malepe e tasi.","also":["redundancy"]},{"id":"failover","g":"run","word":"Sui otometi (Failover)","text":"O le sui otometi i se faiga e sui ai pe a malepe le faiga masani.","also":["failover","fail over"]},{"id":"spof","g":"run","word":"Mea e tasi e malepe ai mea uma (SPOF)","text":"O se vaega e tasi e taofia ai mea uma pe a malepe, ona e leai se mea e sui ai.","also":["single point of failure","single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Taimi o le tausiga (Maintenance window)","text":"O se taimi ua fuafuaina e mafai ai ona taofi pe faatuai se auaunaga mo le tausiga, ua faasilasila muamua i tagata faʻaoga.","also":["maintenance window","maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Tuuina atu galuega (Handover)","text":"O le tuuina atu o galuega, malamalama ma tiute i se isi tagata po o se 'au, ina ia aua nei misi se mea.","also":["handover","handovers"]},{"id":"kb","g":"run","word":"Fale o malamalama (Knowledge base)","text":"O se aofaʻiga o tusitusiga fesoasoani ma tali, mo tagata faʻaoga ma le 'au.","also":["knowledge base","knowledge bases"]},{"id":"csat","g":"run","word":"Fiafia o tagata faatau (CSAT)","text":"O se togi mai tagata faʻaoga e taʻu mai ai le fiafia o i latou, e masani ona fesiligia pe a tapunia se talosaga.","also":["CSAT","customer satisfaction"]},{"id":"supplier","g":"run","word":"Kamupani e tuʻuina mai (Supplier)","text":"O se kamupani i fafo e te faalagolago i ai, e pei o lau kamupani hosting. E ta'ua foi o se vendor po o se third party.","also":["supplier","suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Tapeina o se auaunaga (Service retirement)","text":"O le tapeina o se auaunaga e faavavau, ma le saogalemu: o le faailoa atu i ona tagata faʻaoga, o le taulimaina o ana faamatalaga ma le ulufale, ma le taofia o ona tau.","also":["service retirement","retiring a service"]},{"id":"eol","g":"run","word":"Iuga o le ola (End of life, EOL)","text":"A le toe maua ai e se oloa ni faafouga po o se lagolago mai le kamupani na faia, o lea e tatau ona suia.","also":["EOL","end-of-life","end of life"]},{"id":"cybersec","g":"sec","word":"Saogalemu i luga o le initoneti (Cybersecurity)","text":"O le puipuia o faiga ma faamatalaga mai le osofaʻia, gaoia po o le faaleagaina.","also":["cybersecurity","cyber security"]},{"id":"authn","g":"sec","word":"Faamaonia o le tagata (Authentication)","text":"O le siakiina po o ai se tasi, e masani i se upu faataga po o se code. E masani ona faapuupuu i le authn.","also":["authentication","authn"]},{"id":"authz","g":"sec","word":"Faatagaga (Authorisation)","text":"O le siakiina o mea ua faatagaina se tasi e fai pe a uma ona e iloa po o ai o ia. E masani ona faapuupuu i le authz.","also":["authorisation","authz","authorization"]},{"id":"mfa","g":"sec","word":"Faamaonia e le gata i le tasi (MFA)","text":"O le ulufale i ni faamaoniga e lua pe sili atu, e pei o se upu faataga ma se code i lau telefoni. E ta'ua foi o le two-factor (2FA).","also":["MFA","2FA","two-factor","two-factor authentication","multi-factor authentication"]},{"id":"sso","g":"sec","word":"Ulufale e tasi (Single sign-on, SSO)","text":"O le ulufale e tasi e ulufale ai i le tele o faiga, e pei o le faʻaogaina o lau akauni o galuega i mea uma.","also":["SSO","single sign-on"]},{"id":"pwmgr","g":"sec","word":"Pule o upu faataga (Password manager)","text":"O se app e faia ai upu faataga malosi ma manatua ai mo oe.","also":["password manager","password managers"]},{"id":"secret","g":"sec","word":"Mea lilo (Secret)","text":"O se upu faataga, ki po o se isi code lilo e faaaoga e se polokalama e ulufale ai i se mea. E le tatau lava ona faasoa pe tusia i totonu o le code.","also":["secret","secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"Ki API (API key)","text":"O se code lilo e mafai ai e se polokalama ona faaaoga le API a se isi auaunaga, ma faailoa ai po o ai o loo faaaogaina (ma totogia) ai.","also":["API key","API keys"]},{"id":"accesstoken","g":"sec","word":"Access token (Pasi le tumau)","text":"O se pasi le tumau e faamaonia ai ua faatagaina se polokalama e ulufale, o lea e le manaʻomia ai lau upu faataga i taimi uma. E le tutusa ma le token o le AI.","also":["access token","access tokens"]},{"id":"encryption","g":"sec","word":"Faalilo (Encryption)","text":"O le faafenumiai o faamatalaga ina ia na o se tasi e iai le ki saʻo e mafai ona faitauina.","also":["encryption","encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"O le auala saogalemu e malaga ai itulau web, e faaalia i le loka i lau browser, ina ia leai se tasi i le va e mafai ona faitau pe suia."},{"id":"cert","g":"sec","word":"Pepa faamaonia SSL/TLS","text":"O se pepa faamaonia fa'adijitale e mafai ai e se uepisaite ona faamaonia po o ai o ia ma faaaoga le HTTPS. E uma lona taimi, o lea e tatau ona toe faafouina.","also":["SSL/TLS certificate","TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Faatagaga (Permissions)","text":"O tulafono mo po o ai e mafai ona vaai pe suia mea fea.","also":["permissions","permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Faatagaga aupito itiiti (Least privilege)","text":"O le tuuina atu i tagata taʻitasi po o polokalama na o le ulufale e moni lava ona latou manaʻomia, ma na o le taimi e manaʻomia ai.","also":["least privilege","principle of least privilege"]},{"id":"rbac","g":"sec","word":"Pulega o le ulufale e tusa ai ma tofiga (RBAC)","text":"O le tuuina atu o le ulufale e tusa ai ma le tofiga, e pei o le tagata matamata po o le tagata faasaʻo, nai lo le tagata taʻitoʻatasi.","also":["RBAC","role-based access","role-based access control"]},{"id":"vuln","g":"sec","word":"Vaivaiga (Vulnerability)","text":"O se vaivaiga e mafai e se tasi ona faaaoga e ulufale ai pe faia ai se afaina.","also":["vulnerability","vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"O se vaivaiga ua iloa e tagata osofaʻi a o leʻi maua e ē na fausia se taimi e faaleleia ai.","also":["zero-day","zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware (Polokalama leaga)","text":"O polokalama leaga, e pei o vairusi, ua faia e faaleagaina, tilotilo faalilolilo po o le gaoi.","also":["malware"]},{"id":"ransomware","g":"sec","word":"Ransomware","text":"O malware e loka ai au faila ma talosaga mai ni tupe e tatala ai. O kopi faasao lelei le puipuiga sili.","also":["ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishing (Sailiga pepelo)","text":"O feʻau pepelo e taumafai e faaseseina oe e tuuina atu upu faataga po o tupe, po o le tatalaina o se mea leaga.","also":["phishing","phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Faaseseina o tagata (Social engineering)","text":"O le faaseseina o tagata, e le o komepiuta, ina ia latou tuuina atu le ulufale, e pei o se valaʻau pepelo mai le “lagolago IT”."},{"id":"firewall","g":"sec","word":"Firewall (Puipui afi)","text":"O se leoleo e filifili po o ā faamatalaga i le feso'ota'iga e mafai ona ulufale mai pe alu atu.","also":["firewall","firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Puʻupuʻu mo virtual private network: o se fesootaʻiga lilo ma faalilo (encrypted) i luga o le initoneti, e masani ona faaaoga e ulufale saogalemu ai i faiga o galuega.","also":["virtual private network","VPN"]},{"id":"ddos","g":"sec","word":"Taofia o auaunaga (DoS, DDoS)","text":"O le faatumuina o se auaunaga i le tele naua o talosaga pepelo ma le mafai ai e tagata moni ona faaaoga. O le DDoS o lona uiga e sau mai komepiuta e tele i le taimi e tasi.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Suʻega o le osofaʻiga (Pen test)","text":"O le totogiina o tagata atamamai faauo e taumafai e ulufale, ina ia maua vaivaiga a o leʻi maua e tagata osofaʻi moni.","also":["pen test","pen testing","penetration testing","pentest","penetration test"]},{"id":"audit","g":"sec","word":"Iloiloga o le saogalemu (Security audit)","text":"O se siaki faaeteete i le lelei o le puipuia o se mea, e faasaga i se lisi o faiga lelei.","also":["security audit","security audits"]},{"id":"threatmodel","g":"sec","word":"Iloiloga o lamatiaga (Threat modelling)","text":"O le mafaufau i po o ai e ono osofaʻi i se mea, pe faapefea, ma le mea e te faia e taofia ai i latou.","also":["threat modelling","threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Tafe o faamatalaga lilo (Data breach)","text":"A tafe atu faamatalaga lilo i tagata e le tatau ona maua, pe leiloa pe suia e aunoa ma se faatagaga.","also":["data breach","data breaches"]},{"id":"pii","g":"sec","word":"Faamatalaga patino (Personal data)","text":"So'o se faamatalaga e uiga i se tagata e mafai ona iloa, e pei o se igoa, tuatusi imeli po o se nofoaga. E ta'ua foi o le PII.","also":["personal data","PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"O le tulafono a Europa i faamatalaga patino (o loo iai i le UK lona lava lomiga): aoina na o mea e te manaʻomia, teu ia saogalemu, ma faataga tagata e vaai pe tape a latou faamatalaga.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Puipuia o faamatalaga (Data protection)","text":"O le tausia lelei o faamatalaga patino e tusa ma le tulafono.","also":["data protection","data protection law"]},{"id":"privacypolicy","g":"sec","word":"Faiga faavae o le lilo (Privacy policy)","text":"O se itulau faalauaitele e taʻu mai ai o ā faamatalaga patino e te aoina, aiseā, ma le mea e te faia i ai.","also":["privacy policy","privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Maliega (Consent)","text":"O le ioe manino ma saoloto a se tagata e faaaoga ana faamatalaga i se auala patino. E mafai ona ia toe faaleaogaina i so'o se taimi.","also":["consent","opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"O se faila laʻitiiti e teu e se uepisaite i lau browser e manatua ai mea, e pei o lou ulufale. O nisi e manaʻomia muamua lau maliega.","also":["cookie","cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Faaitiitia o faamatalaga (Data minimisation)","text":"O le aoina ma le teuina na o faamatalaga patino e moni lava ona e manaʻomia mo le galuega.","also":["data minimisation","data minimization"]},{"id":"retention","g":"sec","word":"Teuina o faamatalaga (Data retention)","text":"O le umi e teu ai faamatalaga a o leʻi tapeina. O le teuina e le sili atu nai lo le manaʻomia e sili ona saogalemu ma e masani ona manaʻomia e le tulafono.","also":["data retention","retention period"]},{"id":"anon","g":"sec","word":"Aveesea o igoa (Anonymisation)","text":"O le suia o faamatalaga ina ia le toe mafai e se tasi ona iloa mai ai po o ai le tagata.","also":["anonymisation","anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Suia o igoa i code (Pseudonymisation)","text":"O le sui o igoa ma isi auiliili i code, ma se ki e teu ese e toe fesoʻotaʻi ai. Ae o faamatalaga patino pea lava.","also":["pseudonymisation","pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Maliega o le taulimaina o faamatalaga (DPA)","text":"O se konekarate e taʻu mai ai le auala e mafai ai e se kamupani e tuʻuina mai ona taulimaina faamatalaga patino mo oe.","also":["DPA","data processing agreement"]},{"id":"dpia","g":"sec","word":"Iloiloga o le aafiaga i le puipuia o faamatalaga (DPIA)","text":"O se vaaiga faaeteete, a o leʻi amata, i le auala e mafai ai e se fuafuaga e faaaoga faamatalaga patino ona aafia ai tagata ma le auala e faaitiitia ai lamatiaga.","also":["DPIA","data protection impact assessment"]},{"id":"auditlog","g":"sec","word":"Faamaumauga o iloiloga (Audit log)","text":"O se faamaumauga o po o ai na faia le a le mea ma afea, ina ia mafai ona siaki mulimuli ane gaoioiga.","also":["audit log","audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Usitaʻi (Compliance)","text":"O le mulimuli i tulafono, tulafono faatonutonu ma tulaga e faatatau iā te oe, ma le mafai ona faaali atu o loo e faia.","also":["compliance","compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"O se tulaga faavaomalo lauiloa mo le pulea o le saogalemu o faamatalaga. E mafai ona maua e kamupani se tusi faamaonia mai ai.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"O se lipoti a Amerika, ua siakina e ē iloilo mai fafo, e faaali ai ua tausia lelei e se kamupani faamatalaga a tagata faatau.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Sooupu","text":"O se AI e galue i se galuega e ia lava: faitau le code, faia suiga, faagaoioi siakiga ma lipotia mai. E siakina pea lana galuega.","also":["agent","agents","sooupu"]},{"id":"token","g":"ai","word":"Token","text":"O fasi tusitusiga laiti e faitau ma tusi e se AI, e tusa ma le tolu vaefā o se upu taʻitasi. E faitauina le faaaogaina o le AI i tokens, o lea o le itiiti o tokens e tele atu ai mea e totoe o lau fuafuaga.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"O se poloaiga laʻitiiti e faagaoioi e ia lava i se taimi tofia, mo se faataitaiga pe a amata se sesisi AI, ina ia faalogo le 'au i au faʻamatalaga.","also":["hooks"]},{"id":"ai","g":"ai","word":"Atamai fai (Artificial intelligence, AI)","text":"O faiga komepiuta e faia mea e masani ona tatou manatu e manaʻomia ai se tagata, e pei o le tusitusi, tali fesili po o le iloa o ata.","also":["AI","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Aʻoaʻoga a masini (Machine learning, ML)","text":"O se auala e aʻoaʻo ai komepiuta ni mamanu mai le tele o faataitaiga, nai lo le tuuina atu o tulafono tonu.","also":["ML","machine learning"]},{"id":"model","g":"ai","word":"Model","text":"O le “mafaufau” ua aʻoaʻoina o se faiga AI, ua faia e ala i le aʻoaʻoina mai i le tele naua o faataitaiga. E eseese tomai, saosaoa ma tau o models.","also":["models","AI model","model AI"],"noTip":1},{"id":"llm","g":"ai","word":"Large language model (LLM)","text":"O se model AI ua aʻoaʻoina i le tele naua o tusitusiga, ina ia mafai ona faitau ma tusi gagana.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"AI e faia mea fou (Generative AI)","text":"O le AI e faia mea fou, e pei o tusitusiga, ata po o code, nai lo le na o le faavasegaina po o le iloaina.","also":["GenAI","Generative AI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"O se polokalama e te talanoa i ai i le gagana masani, e ala i le lolomi po o le tautala.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt (Faatonuga)","text":"O le mea e te tuuina atu i se AI: lau fesili po o faatonuga, faatasi ai ma so'o se mea e te tuu atu i ai. E masani ona sili atu le lelei o tali pe a manino faatonuga.","also":["prompt","prompts"]},{"id":"prompteng","g":"ai","word":"Tusiga o faatonuga (Prompt engineering)","text":"O le tomai e tusi ai faatonuga e maua ai iʻuga e faatuatuaina ma aoga.","also":["prompt engineering"]},{"id":"sysprompt","g":"ai","word":"Faatonuga a le faiga (System prompt)","text":"O faatonuga i tua e maua e se AI a o leʻi amata le talanoaga, e seti ai lona tofiga ma tulafono. E sili atu lo latou mamafa nai lo le mea e te lolomi.","also":["system prompt","system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Context (mea e vaaia e le AI)","text":"O mea uma e mafai e le AI ona vaai a o galue: o faatonuga, au feʻau, faila ua ia faitauina ma tali na muamua.","noTip":1},{"id":"ctxwin","g":"ai","word":"Context window (tapulaʻa o le manatua)","text":"O le tele e mafai e se AI ona taofi i lona mafaufau i le taimi e tasi, e fuaina i tokens. A sili atu ai, e lafoaʻi pe aoteleina vaega tuai.","also":["context window","context windows"]},{"id":"session","g":"ai","word":"Sesisi (Session)","text":"O le talanoaga galue e tasi ma se AI, mai le amataga seʻia maeʻa. E amata se sesisi fou ma se manatuaga gaogao.","also":["session","sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Manatuaga (Memory)","text":"O nota e teu e se AI i le va o sesisi, ina ia manatua au mea e fiafia i ai ma filifiliga ua mavae.","noTip":1},{"id":"hallucination","g":"ai","word":"Fatuga sese (Hallucination)","text":"A fai mai se AI se mea e foliga mai ua mautinoa ae ua fatu pe sese. Siaki mea moni taua.","also":["hallucination","hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Aʻoaʻoga (Training)","text":"O le aʻoaʻoina o se model e ala i le faaali atu iā te ia o le tele naua o faataitaiga, a o leʻi faaaoga e se tasi.","also":["training","trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Faamatalaga aʻoaʻoga (Training data)","text":"O faataitaiga na aʻoaʻo mai ai se model. E gata lona malamalama i le aso na aoina ai na faamatalaga.","also":["training data","training set"]},{"id":"cutoff","g":"ai","word":"Aso mulimuli o le malamalama (Knowledge cutoff)","text":"O le aso e iʻu ai le malamalama o loo i totonu o se AI. E le iloa e ia mea mulimuli ane seʻi vagana ua ia suʻeina.","also":["knowledge cutoff","training cutoff"]},{"id":"finetune","g":"ai","word":"Faaleleia atili (Fine-tuning)","text":"O se aʻoaʻoga faaopoopo o se model o iai e faaaoga ai au lava faataitaiga, ina ia sili atu lona lelei i se galuega patino e tasi.","also":["fine-tuning","fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Faaaogaina (Inference)","text":"O le faaaogaina moni o se model AI e tali ai se mea, e ese mai i le aʻoaʻoina.","also":["inference","model inference"]},{"id":"tooluse","g":"ai","word":"Faaaogaina o meafaigaluega (Tool use)","text":"O le mafai e se AI ona faia mea, e le na o le tautala: faagaoioi poloaiga, faitau faila po o suʻe le upega tafa'ilagi, e ala i meafaigaluega e tuuina atu e le app.","also":["tool use","tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Sooupu laʻititi (Subagent)","text":"O se AI fesoasoani e tuuina atu i ai e se AI autu se galuega laʻitiiti, ona toe maua mai lea e le AI autu le iʻuga.","also":["subagent","subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Sooupu e tele (Multi-agent)","text":"O AI e tele e galulue faatasi i le galuega e tasi, e taʻitasi ma lona vaega, e pei o se 'au laʻitiiti.","also":["multi-agent","multi-agent system"]},{"id":"autonomy","g":"ai","word":"Tutoʻatasi (Autonomy)","text":"O le tele o mea e mafai e se AI ona fai na o ia a o leʻi tatau ona fesili i se tagata.","also":["autonomy","autonomous"]},{"id":"hitl","g":"ai","word":"Tagata i totonu o le taamilosaga (Human in the loop)","text":"O le tuʻuina pea o se tagata i totonu e siaki pe faatagaina mea e faia e le AI i taimi taua. I le AI-gile o oe lea.","also":["human in the loop","human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Pā puipui (Guardrails)","text":"O tapulaʻa ma siaki e tausia saogalemu ai gaoioiga a se AI, e pei o le manaʻomia o le faatagaga a o leʻi ola se mea. E faaitiitia ai le lamatiaga o mea sese, ae e le aveesea atoa.","also":["guardrail","guardrails"]},{"id":"rag","g":"ai","word":"RAG (suʻe muamua ona tali)","text":"O le faataga o se AI e suʻe mea i au lava pepa a o leʻi tali, ina ia faavae ana tali i au mea moni.","also":["RAG","retrieval augmented generation","retrieval-augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"O le liua o tusitusiga i se lisi o numera e puʻeina ai lona uiga, ina ia mafai e le komepiuta ona maua mea e tutusa uiga.","also":["embedding","embeddings"]},{"id":"vectordb","g":"ai","word":"Database vector (Vector database)","text":"O se database ua faia e suʻe ai ia lisi o numera (embeddings), e maua ai mea e tutusa uiga.","also":["vector database","vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"O se auala masani e fesootai ai meafaigaluega ma puna o faamatalaga i app AI, ina ia mafai e le AI ona faaaoga.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Vevela (Temperature)","text":"O se seti mo le lototele o tali a se AI. O le maualalo e tuuina mai ai tali e sili ona mautu ma faigofie ona muai iloa; o le maualuga e tuuina mai ai tali e sili ona eseese. E leai se tasi e mautinoa ai e saʻo pea.","also":["temperature","model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"E mafai ona galue i ituaiga faamatalaga e sili atu i le tasi, e pei o tusitusiga, ata ma leo.","also":["multimodal","multi-modal"]},{"id":"evals","g":"ai","word":"Iloiloga (Evaluation, eval)","text":"O se suʻega ua fuafuaina o le lelei o le galue a se AI i faataitaiga filifilia, ina ia mafai ona e faatusatusa models po o prompts.","also":["evaluation","eval","evals"]},{"id":"bias","g":"ai","word":"Faaituau (Bias)","text":"A faaituau se AI (po o se tagata) i le itu e tasi ma le le tonu, e masani lava ona o mea na aʻoaʻo mai ai.","also":["bias","biased"],"noTip":1},{"id":"responsible","g":"ai","word":"AI ma le tiute (Responsible AI)","text":"O le faaaogaina o le AI ma le tonu, saogalemu ma le faamaoni, ma tagata o loo tali pea mo iʻuga.","also":["responsible AI","ethical AI"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"O se togafiti e taumafai ai faatonuga natia i se itulau web po o se faila e faia ai e se AI se mea e leʻi ole atu ai lona tagata faʻaoga.","also":["prompt injection","prompt injections"]},{"id":"ratelimit","g":"ai","word":"Tapulaʻa o talosaga (Rate limit)","text":"O se tapulaʻa i le fia o talosaga e mafai ona e auina atu i se auaunaga i se taimi tofia. A sili atu, e tatau ona e faatali.","also":["rate limit","rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Tapulaʻa o le faʻaaogaina (Usage limit)","text":"O le tele o galuega AI e faatagaina e lau fuafuaga i se vaitaimi; a oo i ai, e taofi pe sili atu le tau.","also":["usage limit","usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"O le fausiaina o polokalama e tele lava e ala i le faamatalaina atu i se AI o le mea e te manaʻo i ai, ma tuu atu iā te ia e tusi le code.","also":["vibe coding","vibe-coding"]},{"id":"budget","g":"money","word":"Tupe ua tofia (Budget)","text":"O le aofaʻi o tupe ua tuuese mo se mea.","also":["budget","budgets"],"noTip":1},{"id":"costest","g":"money","word":"Taumatematega o le tau (Cost estimate)","text":"O se taumatematega sili ona lelei i le tau o se mea a o leʻi amata.","also":["cost estimate","cost estimates"]},{"id":"roi","g":"money","word":"Toe maua mai le tupe faʻaaoga (ROI)","text":"O le mea e te toe maua pe a faatusatusa i le mea na e tuu atu. A sili atu le mea e toe maua, ua aoga.","also":["ROI","return on investment"]},{"id":"tco","g":"money","word":"Aofaʻi o le tau atoa (TCO)","text":"O mea uma e moni lava ona tau ai se mea i lona olaga atoa, e le na o le tau e faatau ai: faagaoioiga, lagolago, faafouga ma le faamutaina i le iʻuga.","also":["TCO","total cost of ownership"]},{"id":"capex","g":"money","word":"CapEx ma OpEx","text":"O le CapEx o tupe e faaalu muamua mo mea e te teuina; o le OpEx o faaaluga faaauau, e pei o pili masina.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Totogi masani (Subscription)","text":"O le totogi soo, e masani i masina taʻitasi po o tausaga taʻitasi, e faaauau ai ona faaaoga se mea.","also":["subscription","subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Polokalama o se auaunaga (SaaS)","text":"O polokalama e te faaaoga i luga o le initoneti ma totogi e ala i se totogi masani (subscription), a o faagaoioia e le kamupani na faia mo oe.","also":["SaaS","software as a service"]},{"id":"payg","g":"money","word":"Totogi i le mea e faaaoga (Pay as you go)","text":"O le totogi na o le mea e te faaaoga, e pei o le cloud computing po o tokens AI.","also":["pay as you go","pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Mea e sili atu (Overage)","text":"O le faaaogaina e sili atu i le mea o loo aofia i lau fuafuaga, lea e mafai ona iai se totogi faaopoopo.","also":["overage","overages","overage charges"]},{"id":"billingalert","g":"money","word":"Lapataiga o tala tupe (Billing alert)","text":"O se feʻau pe a oo le faaaluga po o le faaaogaina i se tulaga na e filifilia. E lapataia oe, ae e le o taimi uma e taofia ai isi totogi.","also":["billing alert","billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Tulaga e leai se totogi (Free tier)","text":"O se tulaga e leai se totogi o se auaunaga e totogi, ae iai tapulaʻa. E aoga mo le amata.","also":["free tier","free plan"]},{"id":"pricing","g":"money","word":"Fuafuaga o tau (Pricing plan)","text":"O afifi eseese e faatau atu e se auaunaga, e taʻitasi ma lona lava tau ma tapulaʻa.","also":["pricing plan","pricing plans","price plan"]},{"id":"licence","g":"money","word":"Laisene (Licence)","text":"O tulafono i le auala e mafai ai ona e faʻaoga, kopiina, suia po o le faasoa o se mea na faia e se isi, e pei o polokalama, mataitusi po o ata.","also":["laisene","licence","licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Open source (Punaoa tatala)","text":"O polokalama e mafai e so'o se tasi ona faitau lona code, faʻaoga ma e masani ona suia e aunoa ma se totogi, i lalo o tulafono o lona laisene.","also":["open source","open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Laisene open source","text":"O tulafono o loo sau faatasi ma le code open source. O nisi e faataga oe e faia toeitiiti lava o mea uma (e pei o le MIT); o nisi e ole atu e te faasoa foi au suiga (e pei o le GPL).","also":["open source licence","open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Proprietary (Umia)","text":"E umia e se kamupani ma e le faatagaina e kopi pe suia e aunoa ma se faatagaga. O le faafeagai o le open source.","also":["proprietary","proprietary software"]},{"id":"copyright","g":"money","word":"Aia tatau o le tusitala (Copyright)","text":"O le aia tatau faaletulafono o le tagata na fatuina se galuega e pulea kopi o lana galuega, e aofia ai code ma tusitusiga.","also":["copyright","copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Meatotino mafaufau (Intellectual property, IP)","text":"O manatu ma mea na fatuina e taʻua e le tulafono o ni meatotino, e pei o code, mamanu, igoa ma ata faailoga.","also":["IP","intellectual property"]},{"id":"tos","g":"money","word":"Tulafono o le auaunaga (Terms of service)","text":"O tulafono e te malilie i ai pe a e faaaoga se auaunaga.","also":["terms of service","terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Konekarate (Contract)","text":"O se maliega tusitusia i le va o itu e lua e lagolagoina e le tulafono.","also":["contract","contracts"],"noTip":1},{"id":"sow","g":"money","word":"Faamatalaga o galuega (SOW)","text":"O se pepa e taʻu mai ai le mea tonu e faia, e oo i afea ma le fia le tau.","also":["SOW","statement of work"]},{"id":"fixedprice","g":"money","word":"Tau tumau (Fixed price)","text":"O se tau ua maliega mo le galuega atoa, e tusa lava pe fia le umi.","also":["fixed price","fixed-price"]},{"id":"tm","g":"money","word":"Taimi ma mea (Time and materials)","text":"O le totogiina o itula na galue moni ma mea na faaaoga moni, nai lo se tau ua seti.","also":["time and materials","T&M"]},{"id":"invoice","g":"money","word":"Pili (Invoice)","text":"O se pili e talosaga mai ai le totogi mo galuega ua faia po o oloa ua tuuina atu.","also":["pili","invoice","invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Mau i le kamupani e tuʻuina mai (Vendor lock-in)","text":"A faigata pe taugata tele le alu ese mai se kamupani e tuʻuina mai, ma ua e mau ai i ai.","also":["vendor lock-in","lock-in"]},{"id":"procurement","g":"money","word":"Faatauina (Procurement)","text":"O le faagasologa o le filifilia ma le faatauina mai kamupani e tuʻuina mai.","also":["procurement"]},{"id":"servicecredit","g":"money","word":"Toe totogi o le auaunaga (Service credit)","text":"O tupe e toe foʻi mai po o se faaitiitiga e te maua pe a le ausia e se kamupani e tuʻuina mai lana SLA.","also":["service credit","service credits"]}]}};
